    private static void testAccuracyPhaseF_RaidenResolveAndEnergyRegression() {
        model.character.RaidenShogun baselineRaiden = new model.character.RaidenShogun(
                new model.weapon.TheCatch(), blankArtifact());
        CombatSimulator baseline = simulatorWithExistingCharacter(baselineRaiden);
        baseline.performAction(CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        baseline.performAction(CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.BURST));
        double baselineBurst = baseline.getLastActionDirectDamageCapture();

        model.character.RaidenShogun stackedRaiden = new model.character.RaidenShogun(
                new model.weapon.TheCatch(), blankArtifact());
        CombatSimulator stacked = simulatorWithExistingCharacter(stackedRaiden);
        TestCharacter burstSource = testCharacter(Element.HYDRO);
        stacked.addCharacter(burstSource);
        stacked.performAction(CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        stacked.performAction(CharacterId.SUCROSE,
                new AttackAction("Resolve source burst", 0.0, Element.HYDRO, StatType.BASE_ATK,
                        null, 0.0, false, ActionType.BURST));
        stacked.performAction(CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.BURST));
        double stackedBurst = stacked.getLastActionDirectDamageCapture();

        assertTrue(stackedBurst > baselineBurst,
                "Raiden burst should gain damage from Resolve generated by another burst action");

        model.character.RaidenShogun raiden = new model.character.RaidenShogun(
                new model.weapon.TheCatch(), blankArtifact());
        model.character.Xiangling xiangling = new model.character.Xiangling(
                new model.weapon.TheCatch(), blankArtifact());
        CombatSimulator multiHitBurst = simulatorWithExistingCharacter(raiden);
        multiHitBurst.addCharacter(xiangling);
        multiHitBurst.performAction(CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        multiHitBurst.performAction(CharacterId.XIANGLING,
                CharacterActionRequest.of(CharacterActionKey.BURST));
        assertClose(18.0, raiden.getResolveStacks(), EPS,
                "Raiden Resolve should count Xiangling's multi-hit burst cast once"
                        + " plus one Wishes Unnumbered particle trigger");
    }

    private static void testAccuracyPhaseF_RaidenConstellationLifecycle() {
        model.character.RaidenShogun c0Raiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(0));
        CombatSimulator c0Sim = simulatorWithExistingCharacter(c0Raiden);
        TestCharacter c0Electro = testCharacter(Element.ELECTRO, CharacterId.XIANGLING);
        c0Sim.addCharacter(c0Electro);
        c0Raiden.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), c0Sim);
        c0Electro.markBurstUsed(c0Sim.getCurrentTime());
        c0Sim.performAction(
                CharacterId.XIANGLING,
                raidenResolveSourceBurst("C0 Electro Resolve source"));
        assertClose(12.0, c0Raiden.getResolveStacks(), EPS,
                "Raiden C0 should retain base Resolve gain");

        model.character.RaidenShogun c1Raiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(1));
        CombatSimulator c1Sim = simulatorWithExistingCharacter(c1Raiden);
        TestCharacter c1Electro = testCharacter(Element.ELECTRO, CharacterId.XIANGLING);
        TestCharacter c1Pyro = testCharacter(Element.PYRO, CharacterId.BENNETT);
        c1Sim.addCharacter(c1Electro);
        c1Sim.addCharacter(c1Pyro);
        c1Raiden.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), c1Sim);
        c1Sim.performAction(
                CharacterId.RAIDEN_SHOGUN,
                raidenResolveSourceBurst("Raiden own Burst damage"));
        assertClose(0.0, c1Raiden.getResolveStacks(), EPS,
                "Raiden should not gain Resolve from her own Burst damage");
        c1Electro.markBurstUsed(c1Sim.getCurrentTime());
        c1Sim.performAction(
                CharacterId.XIANGLING,
                raidenResolveSourceBurst("C1 Electro Resolve source hit 1"));
        c1Sim.performAction(
                CharacterId.XIANGLING,
                raidenResolveSourceBurst("C1 Electro Resolve source hit 2"));
        assertClose(21.6, c1Raiden.getResolveStacks(), EPS,
                "Raiden C1 should multiply one Electro Burst cast by 1.8 without rounding");
        c1Sim.advanceTime(0.1);
        c1Pyro.markBurstUsed(c1Sim.getCurrentTime());
        c1Sim.performAction(
                CharacterId.BENNETT,
                raidenResolveSourceBurst("C1 Pyro Resolve source"));
        assertClose(36.0, c1Raiden.getResolveStacks(), EPS,
                "Raiden C1 should multiply a non-Electro Burst cast by 1.2");
        for (int i = 0; i < 2; i++) {
            c1Sim.advanceTime(0.1);
            c1Electro.markBurstUsed(c1Sim.getCurrentTime());
            c1Sim.performAction(
                    CharacterId.XIANGLING,
                    raidenResolveSourceBurst("C1 capped Electro source " + i));
        }
        assertClose(60.0, c1Raiden.getResolveStacks(), EPS,
                "Raiden C1 Resolve should remain capped at sixty");

        model.character.RaidenShogun c3Raiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(3));
        CombatSimulator c3Sim = simulatorWithExistingCharacter(c3Raiden);
        c3Raiden.onAction(CharacterActionRequest.of(CharacterActionKey.BURST), c3Sim);
        c3Sim.advanceTime(7.01);
        assertTrue(c3Sim.getTeamBuffList().stream().noneMatch(
                        buff -> buff.getId() == BuffId.RAIDEN_C4_PLEDGE_OF_PROPRIETY),
                "Raiden C3 should not apply the C4 end-state buff");

        model.character.RaidenShogun c4Raiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(4));
        CombatSimulator c4Sim = simulatorWithExistingCharacter(c4Raiden);
        TestCharacter c4Ally = testCharacter(Element.PYRO, CharacterId.BENNETT);
        c4Sim.addCharacter(c4Ally);
        c4Raiden.onAction(CharacterActionRequest.of(CharacterActionKey.BURST), c4Sim);
        double c4CastEnd = c4Sim.getCurrentTime();
        c4Sim.advanceTime(6.999);
        assertTrue(c4Raiden.isFormActive(c4Sim.getCurrentTime()),
                "Raiden Musou Isshin should remain active before seven post-cast seconds");
        assertClose(0.0, resolvedStat(c4Sim, c4Ally, StatType.ATK_PERCENT), EPS,
                "Raiden C4 should not apply before Musou Isshin ends");
        c4Sim.advanceTime(0.001 + 1e-9);
        assertTrue(!c4Raiden.isFormActive(c4Sim.getCurrentTime()),
                "Raiden Musou Isshin should end seven seconds after cast resolution");
        Buff normalEndBuff = requireRaidenC4Buff(c4Sim);
        assertClose(c4CastEnd + 7.0, normalEndBuff.getStartTime(), EPS,
                "Raiden C4 normal window should start at post-cast Musou expiry");
        assertClose(0.30, resolvedStat(c4Sim, c4Ally, StatType.ATK_PERCENT), EPS,
                "Raiden C4 should grant allies thirty percent ATK");
        assertClose(0.0, resolvedStat(c4Sim, c4Raiden, StatType.ATK_PERCENT), EPS,
                "Raiden C4 should exclude Raiden herself");
        c4Sim.advanceTime(9.999 - 1e-9);
        assertClose(0.30, resolvedStat(c4Sim, c4Ally, StatType.ATK_PERCENT), EPS,
                "Raiden C4 should remain active before ten seconds");
        c4Sim.advanceTime(0.001 + 1e-9);
        assertClose(0.0, resolvedStat(c4Sim, c4Ally, StatType.ATK_PERCENT), EPS,
                "Raiden C4 should be absent at its exact ten-second expiry");

        model.character.RaidenShogun earlyRaiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(4));
        CombatSimulator earlySim = simulatorWithExistingCharacter(earlyRaiden);
        TestCharacter earlyAlly = testCharacter(Element.PYRO, CharacterId.BENNETT);
        earlySim.addCharacter(earlyAlly);
        earlyRaiden.onAction(CharacterActionRequest.of(CharacterActionKey.BURST), earlySim);
        double earlyCastEnd = earlySim.getCurrentTime();
        earlySim.advanceTime(2.0);
        double switchTime = earlySim.getCurrentTime();
        earlySim.switchCharacter(CharacterId.BENNETT);
        Buff earlyBuff = requireRaidenC4Buff(earlySim);
        assertClose(switchTime, earlyBuff.getStartTime(), EPS,
                "Raiden C4 should start when a standard switch ends Musou early");
        earlySim.advanceTime(earlyCastEnd + 7.001 - earlySim.getCurrentTime());
        Buff afterStaleTimer = requireRaidenC4Buff(earlySim);
        assertClose(switchTime, afterStaleTimer.getStartTime(), EPS,
                "Raiden's stale normal-end timer should not refresh an early C4 window");
        earlySim.advanceTime(switchTime + 9.999 - earlySim.getCurrentTime());
        assertClose(0.30, resolvedStat(earlySim, earlyAlly, StatType.ATK_PERCENT), EPS,
                "Early Raiden C4 should remain active before ten seconds");
        earlySim.advanceTime(0.001 + 1e-9);
        assertClose(0.0, resolvedStat(earlySim, earlyAlly, StatType.ATK_PERCENT), EPS,
                "Early Raiden C4 should expire at ten seconds");

        model.character.RaidenShogun replacedRaiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(4));
        CombatSimulator replacedSim = simulatorWithExistingCharacter(replacedRaiden);
        replacedRaiden.onAction(CharacterActionRequest.of(CharacterActionKey.BURST), replacedSim);
        double firstCastEnd = replacedSim.getCurrentTime();
        replacedSim.advanceTime(1.0);
        replacedRaiden.onAction(CharacterActionRequest.of(CharacterActionKey.BURST), replacedSim);
        double replacementCastEnd = replacedSim.getCurrentTime();
        replacedSim.advanceTime(firstCastEnd + 7.001 - replacedSim.getCurrentTime());
        assertTrue(replacedRaiden.isFormActive(replacedSim.getCurrentTime()),
                "A stale timer should not end a replacement Musou Isshin state");
        assertTrue(replacedSim.getTeamBuffList().stream().noneMatch(
                        buff -> buff.getId() == BuffId.RAIDEN_C4_PLEDGE_OF_PROPRIETY),
                "A stale timer should not create a C4 buff for the replacement state");
        replacedSim.advanceTime(
                replacementCastEnd + 7.0 - replacedSim.getCurrentTime() + 1e-9);
        assertTrue(!replacedRaiden.isFormActive(replacedSim.getCurrentTime()),
                "The replacement Musou state should end on its own timer");
        requireRaidenC4Buff(replacedSim);
    }

    private static AttackAction raidenResolveSourceBurst(String name) {
        return new AttackAction(
                name, 0.0, Element.PHYSICAL, StatType.BASE_ATK,
                null, 0.0, false, ActionType.BURST);
    }

    private static void testAccuracyPhaseF_RaidenC6WishbearerLifecycle() {
        model.character.RaidenShogun raiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(6));
        CombatSimulator sim = simulatorWithExistingCharacter(raiden);
        TestCharacter firstAlly = testCharacter(
                Element.PYRO, CharacterId.XIANGLING);
        TestCharacter secondAlly = testCharacter(
                Element.PYRO, CharacterId.BENNETT);
        TestCharacter readyAlly = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        firstAlly.setBurstCD(20.0);
        secondAlly.setBurstCD(10.0);
        readyAlly.setBurstCD(20.0);
        firstAlly.markBurstUsed(0.0);
        secondAlly.markBurstUsed(0.0);
        sim.addCharacter(firstAlly);
        sim.addCharacter(secondAlly);
        sim.addCharacter(readyAlly);

        raiden.onAction(
                CharacterActionRequest.of(CharacterActionKey.BURST), sim);
        assertClose(20.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "Raiden's initial Burst cast should not trigger Wishbearer");
        assertClose(18.0, raiden.getBurstCooldownEndTime(), EPS,
                "Raiden should start and retain her own Burst cooldown");

        AttackAction normal = wishbearerHit(
                "Wishbearer Normal fixture", ActionType.NORMAL);
        AttackAction charged = wishbearerHit(
                "Wishbearer Charged fixture", ActionType.CHARGE);
        AttackAction plunge = wishbearerHit(
                "Wishbearer Plunging fixture", ActionType.PLUNGE);
        sim.notifyDamage(raiden, normal, 100.0);
        assertClose(19.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "First Wishbearer hit should reduce the first ally by one second");
        assertClose(9.0, secondAlly.getBurstCooldownEndTime(), EPS,
                "Wishbearer should reduce every other pending Burst cooldown");
        assertClose(-999.0, readyAlly.getBurstCooldownEndTime(), EPS,
                "Wishbearer should leave a ready ally cooldown unchanged");
        assertClose(18.0, raiden.getBurstCooldownEndTime(), EPS,
                "Wishbearer should exclude Raiden's own Burst cooldown");
        assertEquals(1, activeBuffCount(
                        raiden,
                        BuffId.RAIDEN_C6_WISHBEARER_TRIGGER,
                        sim.getCurrentTime()),
                "First Wishbearer hit should create one trigger marker");

        SimulatorSnapshot firstTriggerSnapshot = sim.saveSnapshot();
        sim.notifyDamage(raiden, charged, 100.0);
        assertClose(19.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "Same-time multi-hits should share the C6 trigger cooldown");
        sim.advanceTime(0.999);
        sim.notifyDamage(raiden, plunge, 100.0);
        assertClose(19.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "Wishbearer should remain blocked at 0.999 seconds");
        sim.advanceTime(0.001);
        sim.notifyDamage(raiden, plunge, 100.0);
        assertClose(18.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "Wishbearer should reactivate at exactly one second");

        sim.restoreSnapshot(firstTriggerSnapshot);
        assertClose(19.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "Snapshot restore should recover the first C6 reduction");
        assertEquals(1, activeBuffCount(
                        raiden,
                        BuffId.RAIDEN_C6_WISHBEARER_TRIGGER,
                        sim.getCurrentTime()),
                "Snapshot restore should recover one C6 trigger marker");
        sim.advanceTime(1.0);
        sim.notifyDamage(raiden, plunge, 100.0);
        assertClose(18.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "Snapshot replay should reproduce the second C6 reduction");

        AttackAction[] laterHits = { charged, normal, plunge };
        for (AttackAction laterHit : laterHits) {
            sim.advanceTime(1.0);
            sim.notifyDamage(raiden, laterHit, 100.0);
        }
        assertClose(15.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "Five Wishbearer triggers should reduce five seconds total");
        assertEquals(5, activeBuffCount(
                        raiden,
                        BuffId.RAIDEN_C6_WISHBEARER_TRIGGER,
                        sim.getCurrentTime()),
                "Wishbearer should retain five per-state trigger markers");
        sim.advanceTime(1.0);
        sim.notifyDamage(raiden, normal, 100.0);
        assertClose(15.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "A sixth Musou hit should not exceed the five-trigger cap");

        raiden.onAction(
                CharacterActionRequest.of(CharacterActionKey.BURST), sim);
        sim.notifyDamage(raiden, charged, 100.0);
        assertClose(14.0, firstAlly.getBurstCooldownEndTime(), EPS,
                "A replacement Musou state should receive a fresh trigger budget");
        assertEquals(1, activeBuffCount(
                        raiden,
                        BuffId.RAIDEN_C6_WISHBEARER_TRIGGER,
                        sim.getCurrentTime()),
                "Replacement Musou should reset prior trigger markers");

        model.character.RaidenShogun switchRaiden =
                new model.character.RaidenShogun(
                        new TestWeapon(), blankArtifact(), raidenTalentData(6));
        CombatSimulator switchSim = simulatorWithExistingCharacter(switchRaiden);
        TestCharacter switchAlly = testCharacter(
                Element.PYRO, CharacterId.BENNETT);
        switchAlly.setBurstCD(20.0);
        switchAlly.markBurstUsed(0.0);
        switchSim.addCharacter(switchAlly);
        switchRaiden.onAction(
                CharacterActionRequest.of(CharacterActionKey.BURST), switchSim);
        switchRaiden.onAction(
                CharacterActionRequest.of(CharacterActionKey.NORMAL), switchSim);
        assertClose(19.0, switchAlly.getBurstCooldownEndTime(), EPS,
                "An actual Musou Normal hit should trigger Wishbearer");
        switchSim.switchCharacter(CharacterId.BENNETT);
        assertTrue(!switchRaiden.isFormActive(switchSim.getCurrentTime()),
                "Switching should end Musou before later C6 callbacks");
        assertEquals(0, activeBuffCount(
                        switchRaiden,
                        BuffId.RAIDEN_C6_WISHBEARER_TRIGGER,
                        switchSim.getCurrentTime()),
                "Switching should clear Wishbearer trigger markers");
        double switchEndCooldown = switchAlly.getBurstCooldownEndTime();
        switchSim.notifyDamage(switchRaiden, normal, 100.0);
        assertClose(switchEndCooldown,
                switchAlly.getBurstCooldownEndTime(),
                EPS,
                "Post-form hits should not trigger Wishbearer");

        model.character.RaidenShogun rejectedRaiden =
                new model.character.RaidenShogun(
                        new TestWeapon(), blankArtifact(), raidenTalentData(6));
        CombatSimulator rejectedSim = simulatorWithExistingCharacter(
                rejectedRaiden);
        TestCharacter rejectedAlly = testCharacter(
                Element.PYRO, CharacterId.BENNETT);
        TestCharacter foreignActor = testCharacter(
                Element.ELECTRO, CharacterId.XIANGLING);
        rejectedAlly.setBurstCD(20.0);
        rejectedAlly.markBurstUsed(0.0);
        rejectedSim.addCharacter(rejectedAlly);
        rejectedSim.addCharacter(foreignActor);
        rejectedRaiden.onAction(
                CharacterActionRequest.of(CharacterActionKey.BURST), rejectedSim);
        rejectedSim.notifyDamage(
                rejectedRaiden,
                typedDamageHit(
                        "Wishbearer Physical fixture", ActionType.NORMAL, 1.0),
                100.0);
        rejectedSim.notifyDamage(foreignActor, normal, 100.0);
        rejectedSim.notifyDamage(rejectedRaiden, normal, 0.0);
        rejectedSim.notifyDamage(rejectedRaiden, normal, -1.0);
        rejectedSim.setEnemy(null);
        rejectedSim.notifyDamage(rejectedRaiden, normal, 100.0);
        assertClose(20.0, rejectedAlly.getBurstCooldownEndTime(), EPS,
                "Invalid Wishbearer callbacks should preserve ally cooldowns");

        model.character.RaidenShogun c5Raiden = new model.character.RaidenShogun(
                new TestWeapon(), blankArtifact(), raidenTalentData(5));
        CombatSimulator c5Sim = simulatorWithExistingCharacter(c5Raiden);
        TestCharacter c5Ally = testCharacter(
                Element.PYRO, CharacterId.BENNETT);
        c5Ally.setBurstCD(20.0);
        c5Ally.markBurstUsed(0.0);
        c5Sim.addCharacter(c5Ally);
        c5Raiden.onAction(
                CharacterActionRequest.of(CharacterActionKey.BURST), c5Sim);
        c5Sim.notifyDamage(c5Raiden, normal, 100.0);
        assertClose(20.0, c5Ally.getBurstCooldownEndTime(), EPS,
                "C5 Raiden should not run Wishbearer cooldown reduction");
    }

    private static AttackAction wishbearerHit(
            String name, ActionType actionType) {
        AttackAction action = typedDamageHit(name, actionType, 1.0);
        action.setCountsAsBurstDmg(true);
        return action;
    }

    private static void testAccuracyPhaseF_RaidenMultiHitAttackContract() {
        RecordingDamageWeapon physicalWeapon = new RecordingDamageWeapon("Raiden ");
        model.character.RaidenShogun physicalRaiden =
                new model.character.RaidenShogun(
                        physicalWeapon, blankArtifact(), raidenTalentData(0));
        CombatSimulator physicalSim =
                simulatorWithExistingCharacter(physicalRaiden);
        List<AttackAction> physicalLogicalActions = new ArrayList<>();
        physicalSim.addListener(
                (actor, action, time) -> physicalLogicalActions.add(action));
        for (int i = 0; i < 5; i++) {
            physicalSim.performAction(
                    CharacterId.RAIDEN_SHOGUN,
                    CharacterActionRequest.of(CharacterActionKey.NORMAL));
        }
        physicalSim.performAction(
                CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));

        List<AttackAction> physicalN4 = physicalWeapon.actions.stream()
                .filter(action -> action.getName().startsWith("Raiden N4 Hit"))
                .collect(Collectors.toList());
        assertEquals(2, physicalN4.size(),
                "Raiden physical N4 should resolve two damage hits");
        assertEquals("Raiden N4 Hit 1", physicalN4.get(0).getName(),
                "Raiden physical N4 first hit name");
        assertEquals("Raiden N4 Hit 2", physicalN4.get(1).getName(),
                "Raiden physical N4 second hit name");
        assertClose(0.5325, physicalN4.get(0).getDamagePercent(), EPS,
                "Raiden physical N4 first multiplier");
        assertClose(0.5325, physicalN4.get(1).getDamagePercent(), EPS,
                "Raiden physical N4 second multiplier");
        assertClose(0.95 + 15.0 / 60.0, physicalWeapon.times.get(3), EPS,
                "Raiden physical N4 first hit timestamp");
        assertClose(0.95 + 15.0 / 60.0, physicalWeapon.times.get(4), EPS,
                "Raiden physical N4 second hit timestamp");
        assertClose(2.85 + 25.0 / 60.0, physicalSim.getCurrentTime(), EPS,
                "Raiden physical combo and Charged should include owner hitlag");
        assertEquals(7, physicalWeapon.actions.size(),
                "Only Raiden physical N4 should add one extra damage event");
        assertEquals(6, physicalLogicalActions.size(),
                "Raiden physical requests should emit one logical event each");
        assertEquals("Raiden N4 Hit 2", physicalLogicalActions.get(3).getName(),
                "Raiden physical N4 final hit should own the logical event");
        assertEquals("Raiden N5", physicalWeapon.actions.get(5).getName(),
                "Raiden N5 should remain one hit after split N4");
        assertEquals("Raiden CA", physicalWeapon.actions.get(6).getName(),
                "Raiden physical Charged should remain one hit");
        for (int index : new int[] { 0, 1, 2, 5, 6 }) {
            assertHitlagProfile(
                    physicalWeapon.actions.get(index),
                    0.02,
                    0.01,
                    true,
                    false,
                    "Raiden physical profile at index " + index);
        }
        assertNoHitlagProfile(physicalN4.get(0),
                "Raiden physical N4 first hit should have no hitlag");
        assertNoHitlagProfile(physicalN4.get(1),
                "Raiden physical N4 second hit should have no hitlag");

        RecordingDamageWeapon musouWeapon = new RecordingDamageWeapon("Raiden ");
        model.character.RaidenShogun musouRaiden =
                new model.character.RaidenShogun(
                        musouWeapon, blankArtifact(), raidenTalentData(2));
        CombatSimulator musouSim = simulatorWithExistingCharacter(musouRaiden);
        TestCharacter resolveSource =
                testCharacter(Element.HYDRO, CharacterId.XIANGLING);
        musouSim.addCharacter(resolveSource);
        musouSim.performAction(
                CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        resolveSource.markBurstUsed(musouSim.getCurrentTime());
        musouSim.performAction(
                CharacterId.XIANGLING,
                raidenResolveSourceBurst("Raiden multi-hit Resolve source"));
        assertClose(14.4, musouRaiden.getResolveStacks(), EPS,
                "Raiden C2 fixture should include its inherited C1 Resolve bonus");
        musouSim.performAction(
                CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.BURST));
        double musouNormalStart = musouSim.getCurrentTime();
        for (int i = 0; i < 4; i++) {
            musouSim.performAction(
                    CharacterId.RAIDEN_SHOGUN,
                    CharacterActionRequest.of(CharacterActionKey.NORMAL));
        }

        List<AttackAction> musouN4 = musouWeapon.actions.stream()
                .filter(action -> action.getName().startsWith(
                        "Raiden Burst N4 Hit"))
                .collect(Collectors.toList());
        assertEquals(2, musouN4.size(),
                "Raiden Musou N4 should resolve two damage hits");
        double resolvePerHit = 14.4 * 0.0123;
        assertClose(0.5195 + resolvePerHit,
                musouN4.get(0).getDamagePercent(), EPS,
                "Raiden Musou N4 first multiplier and Resolve");
        assertClose(0.5210 + resolvePerHit,
                musouN4.get(1).getDamagePercent(), EPS,
                "Raiden Musou N4 second multiplier and Resolve");
        for (AttackAction hit : musouN4) {
            assertTrue(hit.isCountsAsBurstDmg(),
                    "Every Raiden Musou N4 hit should count as Burst damage");
            assertClose(0.60, hit.getDefenseIgnore(), EPS,
                    "Every Raiden C2 Musou N4 hit should ignore DEF");
            assertEquals(ICDType.Standard, hit.getICDType(),
                    "Every Raiden Musou N4 hit should use standard ICD");
            assertEquals(ICDTag.Raiden_MusouIsshin, hit.getICDTag(),
                    "Every Raiden Musou N4 hit should share the Musou ICD tag");
            assertNoHitlagProfile(hit,
                    "Every Raiden Musou N4 hit should have no hitlag");
        }
        assertClose(musouNormalStart + 1.4 + 15.0 / 60.0,
                musouSim.getCurrentTime(), EPS,
                "Raiden Musou N1-N4 should include three hitlag intervals");

        double musouChargeStart = musouSim.getCurrentTime();
        musouSim.performAction(
                CharacterId.RAIDEN_SHOGUN,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));
        List<AttackAction> musouCharge = musouWeapon.actions.stream()
                .filter(action -> action.getName().startsWith(
                        "Raiden Burst CA Hit"))
                .collect(Collectors.toList());
        assertEquals(2, musouCharge.size(),
                "Raiden Musou Charged should resolve two damage hits");
        assertClose(1.036 + resolvePerHit,
                musouCharge.get(0).getDamagePercent(), EPS,
                "Raiden Musou Charged first multiplier and Resolve");
        assertClose(1.2506 + resolvePerHit,
                musouCharge.get(1).getDamagePercent(), EPS,
                "Raiden Musou Charged second multiplier and Resolve");
        for (AttackAction hit : musouCharge) {
            assertEquals(ActionType.CHARGE, hit.getActionType(),
                    "Every Raiden Musou Charged hit should retain Charged typing");
            assertTrue(hit.isCountsAsBurstDmg(),
                    "Every Raiden Musou Charged hit should count as Burst damage");
            assertClose(0.60, hit.getDefenseIgnore(), EPS,
                    "Every Raiden C2 Musou Charged hit should ignore DEF");
            assertEquals(ICDTag.Raiden_MusouIsshin, hit.getICDTag(),
                    "Every Raiden Musou Charged hit should share the Musou ICD tag");
        }
        assertNoHitlagProfile(musouCharge.get(0),
                "Raiden Musou Charged first hit should have no hitlag");
        assertHitlagProfile(
                musouCharge.get(1), 0.02, 0.01, true, false,
                "Raiden Musou Charged second hit profile");
        int chargeStartIndex = musouWeapon.actions.indexOf(musouCharge.get(0));
        assertClose(musouChargeStart, musouWeapon.times.get(chargeStartIndex), EPS,
                "Raiden Musou Charged first hit timestamp");
        assertClose(musouChargeStart,
                musouWeapon.times.get(chargeStartIndex + 1), EPS,
                "Raiden Musou Charged second hit timestamp");
        assertClose(musouChargeStart + 0.8 + 5.0 / 60.0,
                musouSim.getCurrentTime(), EPS,
                "Raiden Musou Charged should include second-hit owner hitlag");
    }

    private static Buff requireRaidenC4Buff(CombatSimulator sim) {
        List<Buff> buffs = new ArrayList<>();
        for (Buff buff : sim.getTeamBuffList()) {
            if (buff.getId() == BuffId.RAIDEN_C4_PLEDGE_OF_PROPRIETY) {
                buffs.add(buff);
            }
        }
        assertEquals(1, buffs.size(),
                "Raiden C4 should retain exactly one typed team buff");
        assertEquals(CharacterId.RAIDEN_SHOGUN, buffs.get(0).getSourceCharacterId(),
                "Raiden C4 should retain typed source ownership");
        return buffs.get(0);
    }

    private static void testAccuracyPhaseF_FlinsChargedAttackCoverage() {
        RecordingDamageWeapon physicalWeapon = new RecordingDamageWeapon(
                "Flins Charged Attack");
        model.character.Flins physicalFlins = new model.character.Flins(
                physicalWeapon, blankArtifact(), flinsTalentData(0));
        CombatSimulator physicalSim = simulatorWithExistingCharacter(
                physicalFlins);
        List<AttackAction> logicalActions = new ArrayList<>();
        physicalSim.addListener((actor, action, time) ->
                logicalActions.add(action));
        physicalSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));
        AttackAction physicalCharged = physicalWeapon.actions.get(0);
        assertClose(1.8928, physicalCharged.getDamagePercent(), EPS,
                "Flins Charged should use its sourced level-9 multiplier");
        assertEquals(Element.PHYSICAL, physicalCharged.getElement(),
                "Flins Charged should deal Physical damage outside form");
        assertEquals(ActionType.CHARGE, physicalCharged.getActionType(),
                "Flins Charged should retain typed action category");
        assertEquals(StatType.CHARGED_ATTACK_DMG_BONUS,
                physicalCharged.getBonusStat(),
                "Flins Charged should use Charged DMG Bonus");
        assertEquals(ICDType.Standard, physicalCharged.getICDType(),
                "Flins Charged should use standard ICD");
        assertEquals(ICDTag.ChargedAttack, physicalCharged.getICDTag(),
                "Flins Charged should use the Charged ICD group");
        assertClose(1.0, physicalCharged.getGaugeUnits(), EPS,
                "Flins Charged should apply 1U when infused");
        assertClose(0.8, physicalSim.getCurrentTime(), EPS,
                "Flins Charged should use the polearm action-duration approximation");

        physicalSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.NORMAL));
        physicalSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.NORMAL));
        physicalSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));
        physicalSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.NORMAL));
        assertEquals("Flins N1",
                logicalActions.get(logicalActions.size() - 1).getName(),
                "Flins Charged should reset the Normal combo to N1");

        RecordingDamageWeapon manifestWeapon = new RecordingDamageWeapon("");
        model.character.Flins manifestFlins = new model.character.Flins(
                manifestWeapon, blankArtifact(), flinsTalentData(2));
        CombatSimulator manifestSim = simulatorWithExistingCharacter(
                manifestFlins);
        manifestSim.setMoonsign(CombatSimulator.Moonsign.ASCENDANT_GLEAM);
        manifestSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        manifestSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        manifestSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));
        AttackAction manifestCharged = manifestWeapon.actions.stream()
                .filter(action -> action.getName().equals(
                        "Flins Charged Attack (Manifest)"))
                .findFirst()
                .orElseThrow();
        assertEquals(Element.ELECTRO, manifestCharged.getElement(),
                "Manifest Flame should convert Charged damage to Electro");
        assertClose(1.8928, manifestCharged.getDamagePercent(), EPS,
                "Manifest Charged should retain the Normal-talent multiplier");
        assertClose(0.25,
                resolvedStat(
                        manifestSim,
                        manifestFlins,
                        StatType.ELECTRO_RES_SHRED),
                EPS,
                "In-form Charged damage should run the existing C2 shred hook");
        assertEquals(0L, manifestWeapon.actions.stream()
                        .filter(action -> action.getName().equals(
                                "The Devil's Wall Follow-Up"))
                        .count(),
                "Charged should not consume C2's next-Normal follow-up");
        manifestSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.NORMAL));
        assertEquals(1L, manifestWeapon.actions.stream()
                        .filter(action -> action.getName().equals(
                                "The Devil's Wall Follow-Up"))
                        .count(),
                "The next in-form Normal should still consume the C2 follow-up");

        RecordingDamageWeapon c5Weapon = new RecordingDamageWeapon(
                "Flins Charged Attack");
        model.character.Flins c5Flins = new model.character.Flins(
                c5Weapon, blankArtifact(), flinsTalentData(5));
        CombatSimulator c5Sim = simulatorWithExistingCharacter(c5Flins);
        c5Sim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        c5Sim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));
        assertClose(1.8928,
                c5Weapon.actions.get(0).getDamagePercent(),
                EPS,
                "Flins C5 should not alter the Normal-talent Charged multiplier");

        RecordingDamageWeapon boundaryWeapon = new RecordingDamageWeapon(
                "Flins Charged Attack");
        model.character.Flins boundaryFlins = new model.character.Flins(
                boundaryWeapon, blankArtifact(), flinsTalentData(0));
        CombatSimulator boundarySim = simulatorWithExistingCharacter(
                boundaryFlins);
        boundarySim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        SimulatorSnapshot activeFormSnapshot = boundarySim.saveSnapshot();
        boundarySim.advanceTime(
                9.999 - boundarySim.getCurrentTime());
        boundarySim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));
        assertEquals(Element.ELECTRO,
                boundaryWeapon.actions.get(0).getElement(),
                "Flins Charged should remain Electro just before form expiry");
        boundarySim.restoreSnapshot(activeFormSnapshot);
        boundaryWeapon.actions.clear();
        boundarySim.advanceTime(10.0 - boundarySim.getCurrentTime());
        boundarySim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.CHARGE));
        assertEquals(Element.PHYSICAL,
                boundaryWeapon.actions.get(0).getElement(),
                "Flins Charged should become Physical at exact form expiry");
    }

    private static void testAccuracyPhaseF_FlinsHighPlungeCoverage() {
        RecordingDamageWeapon weapon = new RecordingDamageWeapon("Flins ");
        model.character.Flins flins = new model.character.Flins(
                weapon, blankArtifact(), flinsTalentData(0));
        CombatSimulator sim = simulatorWithExistingCharacter(flins);
        sim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.NORMAL));
        sim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.NORMAL));
        double plungeStart = sim.getCurrentTime();
        sim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.PLUNGE));
        AttackAction plunge = weapon.actions.stream()
                .filter(action -> action.getName().equals("Flins High Plunge"))
                .findFirst()
                .orElseThrow();
        assertClose(2.9336, plunge.getDamagePercent(), EPS,
                "Flins Plunge should use its sourced level-9 multiplier");
        assertEquals(Element.PHYSICAL, plunge.getElement(),
                "Flins Plunge should deal Physical damage outside form");
        assertEquals(ActionType.PLUNGE, plunge.getActionType(),
                "Flins Plunge should retain typed action metadata");
        assertEquals(StatType.PLUNGING_ATTACK_DMG_BONUS, plunge.getBonusStat(),
                "Flins Plunge should use Plunging DMG Bonus");
        assertEquals(ICDType.None, plunge.getICDType(),
                "Flins high Plunge should have no ICD");
        assertEquals(ICDTag.None, plunge.getICDTag(),
                "Flins high Plunge should not enter an elemental ICD group");
        assertClose(1.0, plunge.getGaugeUnits(), EPS,
                "Flins high Plunge should retain 1U metadata");
        assertClose(plungeStart + 1.0, sim.getCurrentTime(), EPS,
                "Flins high Plunge should use the one-second approximation");
        sim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.NORMAL));
        assertEquals("Flins N1", weapon.actions.get(weapon.actions.size() - 1).getName(),
                "Flins Plunge should reset the Normal combo");

        RecordingDamageWeapon formWeapon = new RecordingDamageWeapon("Flins ");
        model.character.Flins formFlins = new model.character.Flins(
                formWeapon, blankArtifact(), flinsTalentData(0));
        CombatSimulator formSim = simulatorWithExistingCharacter(formFlins);
        formSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.SKILL));
        int activeActionCount = formWeapon.actions.size();
        double activeTime = formSim.getCurrentTime();
        boolean activeRejected = false;
        try {
            formSim.performAction(
                    CharacterId.FLINS,
                    CharacterActionRequest.of(CharacterActionKey.PLUNGE));
        } catch (IllegalStateException expected) {
            activeRejected = true;
        }
        assertTrue(activeRejected,
                "Flins should reject Plunge while Manifest Flame is active");
        assertEquals(activeActionCount, formWeapon.actions.size(),
                "Rejected Manifest Plunge should not deal damage");
        assertClose(activeTime, formSim.getCurrentTime(), EPS,
                "Rejected Manifest Plunge should not advance simulation time");

        formSim.advanceTime(10.0 - formSim.getCurrentTime());
        formSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.PLUNGE));
        AttackAction boundaryPlunge = formWeapon.actions.stream()
                .filter(action -> action.getName().equals("Flins High Plunge"))
                .findFirst()
                .orElseThrow();
        assertEquals(Element.PHYSICAL, boundaryPlunge.getElement(),
                "Flins Plunge should become available at exact form expiry");

        double dashStart = formSim.getCurrentTime();
        int beforeDashActions = formWeapon.actions.size();
        formSim.performAction(
                CharacterId.FLINS,
                CharacterActionRequest.of(CharacterActionKey.DASH));
        assertClose(dashStart + 0.4, formSim.getCurrentTime(), EPS,
                "Flins Dash should remain supported after adding Plunge");
        assertEquals(beforeDashActions, formWeapon.actions.size(),
                "Flins Dash should not create a damage action");
    }

    private static void testAccuracyPhaseF_FlinsA1AndC1Lifecycle() {
        model.character.Flins c0Flins = new model.character.Flins(
                new TestWeapon(), blankArtifact(), flinsTalentData(0));
        CombatSimulator c0Sim = simulatorWithExistingCharacter(c0Flins);
        c0Flins.spendEnergy(c0Flins.getMaxEnergy());
        c0Sim.notifyReaction(
                ReactionResult.lunar(100.0, ReactionResult.LunarType.CHARGED),
                testCharacter(Element.HYDRO, CharacterId.XINGQIU));
        assertClose(0.0, c0Flins.getCurrentEnergy(), EPS,
                "Flins C0 should not restore C1 Energy");
        assertClose(0.0,
                resolvedStat(c0Sim, c0Flins, StatType.LUNAR_CHARGED_DMG_BONUS), EPS,
                "Flins A1 should be absent at Nascent Gleam");
        assertClose(0.0,
                resolvedStat(c0Sim, c0Flins, StatType.LUNAR_UNIQUE_BONUS), EPS,
                "Flins A1 should not use the separate Lunar unique category");
        c0Sim.setMoonsign(CombatSimulator.Moonsign.ASCENDANT_GLEAM);
        assertClose(0.20,
                resolvedStat(c0Sim, c0Flins, StatType.LUNAR_CHARGED_DMG_BONUS), EPS,
                "Flins A1 should grant Lunar-Charged bonus at Ascendant Gleam");
        c0Sim.setMoonsign(CombatSimulator.Moonsign.NASCENT_GLEAM);
        assertClose(0.0,
                resolvedStat(c0Sim, c0Flins, StatType.LUNAR_CHARGED_DMG_BONUS), EPS,
                "Flins A1 should follow live Moonsign transitions");

        model.character.Flins c1Flins = new model.character.Flins(
                new TestWeapon(), blankArtifact(), flinsTalentData(1));
        CombatSimulator c1Sim = simulatorWithExistingCharacter(c1Flins);
        c1Flins.initializeForSimulator(c1Sim);
        c1Flins.spendEnergy(c1Flins.getMaxEnergy());
        TestCharacter reactionSource =
                testCharacter(Element.HYDRO, CharacterId.XINGQIU);
        c1Sim.notifyReaction(
                ReactionResult.transform(
                        100.0, "Electro-Charged", ReactionResult.Kind.ELECTRO_CHARGED),
                reactionSource);
        c1Sim.notifyReaction(
                ReactionResult.lunar(0.0, ReactionResult.LunarType.CHARGED),
                reactionSource);
        c1Sim.notifyReaction(ReactionResult.none(), reactionSource);
        assertClose(0.0, c1Flins.getCurrentEnergy(), EPS,
                "Flins C1 should reject standard, synthetic, and NONE reactions");
        c1Sim.notifyReaction(
                ReactionResult.lunar(100.0, ReactionResult.LunarType.CHARGED),
                reactionSource);
        assertClose(8.0, c1Flins.getCurrentEnergy(), EPS,
                "Flins C1 should restore Energy before Flins's first action");
        c1Sim.advanceTime(5.499);
        c1Sim.notifyReaction(
                ReactionResult.lunar(100.0, ReactionResult.LunarType.CHARGED),
                reactionSource);
        assertClose(8.0, c1Flins.getCurrentEnergy(), EPS,
                "Flins C1 should remain gated before 5.5 seconds");
        c1Sim.advanceTime(0.001);
        c1Sim.notifyReaction(
                ReactionResult.lunar(100.0, ReactionResult.LunarType.CHARGED),
                reactionSource);
        assertClose(16.0, c1Flins.getCurrentEnergy(), EPS,
                "Flins C1 should restore Energy at exactly 5.5 seconds");

        boolean crossSimulatorRejected = false;
        try {
            CombatSimulator otherSim = new CombatSimulator();
            otherSim.setLoggingEnabled(false);
            otherSim.addCharacter(c1Flins);
        } catch (IllegalStateException expected) {
            crossSimulatorRejected = true;
        }
        assertTrue(crossSimulatorRejected,
                "Flins should reject cross-simulator listener reuse");
    }

    private static void testAccuracyPhaseF_FlinsC2AndC4() {
        RecordingDamageWeapon c2Weapon =
                new RecordingDamageWeapon("The Devil's Wall Follow-Up");
        model.character.Flins c2Flins = new model.character.Flins(
                c2Weapon, blankArtifact(), flinsTalentData(2));
        CombatSimulator c2Sim = simulatorWithExistingCharacter(c2Flins);
        c2Flins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), c2Sim);
        c2Flins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), c2Sim);
        c2Flins.onAction(CharacterActionRequest.of(CharacterActionKey.NORMAL), c2Sim);
        assertEquals(1, c2Weapon.actions.size(),
                "Flins C2 should add one follow-up to the first Manifest Normal");
        AttackAction c2FollowUp = c2Weapon.actions.get(0);
        assertClose(0.50, c2FollowUp.getDamagePercent(), EPS,
                "Flins C2 follow-up multiplier");
        assertEquals(Element.ELECTRO, c2FollowUp.getElement(),
                "Flins C2 follow-up element");
        assertEquals(ActionType.OTHER, c2FollowUp.getActionType(),
                "Flins C2 follow-up action category");
        assertEquals(AttackAction.LunarReactionType.CHARGED,
                c2FollowUp.getLunarReactionType(),
                "Flins C2 follow-up should use direct Lunar-Charged damage");
        assertEquals(ICDType.None, c2FollowUp.getICDType(),
                "Flins C2 follow-up should have no ICD");
        assertEquals(ICDTag.None, c2FollowUp.getICDTag(),
                "Flins C2 follow-up should not enter an elemental ICD group");
        assertClose(0.0, c2FollowUp.getGaugeUnits(), EPS,
                "Flins C2 follow-up should apply zero gauge");
        c2Flins.onAction(CharacterActionRequest.of(CharacterActionKey.NORMAL), c2Sim);
        assertEquals(1, c2Weapon.actions.size(),
                "Flins C2 follow-up should be consumed after one Normal hit");

        RecordingDamageWeapon c1Weapon =
                new RecordingDamageWeapon("The Devil's Wall Follow-Up");
        model.character.Flins c1Flins = new model.character.Flins(
                c1Weapon, blankArtifact(), flinsTalentData(1));
        CombatSimulator c1Sim = simulatorWithExistingCharacter(c1Flins);
        c1Flins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), c1Sim);
        c1Flins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), c1Sim);
        c1Flins.onAction(CharacterActionRequest.of(CharacterActionKey.NORMAL), c1Sim);
        assertTrue(c1Weapon.actions.isEmpty(),
                "Flins C1 should not receive the C2 follow-up");

        RecordingDamageWeapon beforeExpiryWeapon =
                new RecordingDamageWeapon("The Devil's Wall Follow-Up");
        model.character.Flins beforeExpiryFlins = new model.character.Flins(
                beforeExpiryWeapon, blankArtifact(), flinsTalentData(2));
        CombatSimulator beforeExpirySim =
                simulatorWithExistingCharacter(beforeExpiryFlins);
        beforeExpiryFlins.onAction(
                CharacterActionRequest.of(CharacterActionKey.SKILL), beforeExpirySim);
        double spearstormCastTime = beforeExpirySim.getCurrentTime();
        beforeExpiryFlins.onAction(
                CharacterActionRequest.of(CharacterActionKey.SKILL), beforeExpirySim);
        beforeExpirySim.advanceTime(
                spearstormCastTime + 5.999 - beforeExpirySim.getCurrentTime());
        beforeExpiryFlins.onAction(
                CharacterActionRequest.of(CharacterActionKey.NORMAL), beforeExpirySim);
        assertEquals(1, beforeExpiryWeapon.actions.size(),
                "Flins C2 follow-up should trigger immediately before six seconds");

        RecordingDamageWeapon atExpiryWeapon =
                new RecordingDamageWeapon("The Devil's Wall Follow-Up");
        model.character.Flins atExpiryFlins = new model.character.Flins(
                atExpiryWeapon, blankArtifact(), flinsTalentData(2));
        CombatSimulator atExpirySim = simulatorWithExistingCharacter(atExpiryFlins);
        atExpiryFlins.onAction(
                CharacterActionRequest.of(CharacterActionKey.SKILL), atExpirySim);
        double atExpiryCastTime = atExpirySim.getCurrentTime();
        atExpiryFlins.onAction(
                CharacterActionRequest.of(CharacterActionKey.SKILL), atExpirySim);
        atExpirySim.advanceTime(
                atExpiryCastTime + 6.0 - atExpirySim.getCurrentTime());
        atExpiryFlins.onAction(
                CharacterActionRequest.of(CharacterActionKey.NORMAL), atExpirySim);
        assertTrue(atExpiryWeapon.actions.isEmpty(),
                "Flins C2 follow-up should be absent at exact six-second expiry");

        model.character.Flins shredFlins = new model.character.Flins(
                new TestWeapon(), blankArtifact(), flinsTalentData(2));
        CombatSimulator shredSim = new CombatSimulator();
        shredSim.setLoggingEnabled(false);
        shredSim.setEnemy(new Enemy(90));
        List<Double> shredDuringTrigger = new ArrayList<>();
        shredSim.addDamageListener((actor, action, damage, time) -> {
            if (actor == shredFlins
                    && "Northland Spearstorm".equals(action.getName())) {
                shredDuringTrigger.add(
                        resolvedStat(shredSim, shredFlins, StatType.ELECTRO_RES_SHRED));
            }
        });
        shredSim.addCharacter(shredFlins);
        shredSim.setMoonsign(CombatSimulator.Moonsign.ASCENDANT_GLEAM);
        shredFlins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), shredSim);
        shredFlins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), shredSim);
        assertEquals(1, shredDuringTrigger.size(),
                "Flins C2 shred ordering fixture should observe Spearstorm once");
        assertClose(0.0, shredDuringTrigger.get(0), EPS,
                "Flins C2 triggering Electro hit should not benefit from its own shred");
        Buff firstShred = requireFlinsC2Shred(shredSim);
        assertClose(0.25,
                resolvedStat(shredSim, shredFlins, StatType.ELECTRO_RES_SHRED), EPS,
                "Flins C2 should apply Electro shred after an on-field hit");
        double firstShredStart = firstShred.getStartTime();
        shredSim.advanceTime(1.0);
        shredFlins.onAction(CharacterActionRequest.of(CharacterActionKey.NORMAL), shredSim);
        Buff refreshedShred = requireFlinsC2Shred(shredSim);
        assertTrue(refreshedShred.getStartTime() > firstShredStart,
                "Flins C2 should refresh rather than stack on later Electro hits");
        double refreshedStart = refreshedShred.getStartTime();
        shredSim.advanceTime(refreshedStart + 6.999 - shredSim.getCurrentTime());
        assertClose(0.25,
                resolvedStat(shredSim, shredFlins, StatType.ELECTRO_RES_SHRED), EPS,
                "Flins C2 shred should remain active before seven seconds");
        shredSim.advanceTime(0.001 + 1e-9);
        assertClose(0.0,
                resolvedStat(shredSim, shredFlins, StatType.ELECTRO_RES_SHRED), EPS,
                "Flins C2 shred should expire at exactly seven seconds");

        model.character.Flins nascentFlins = new model.character.Flins(
                new TestWeapon(), blankArtifact(), flinsTalentData(2));
        CombatSimulator nascentSim = simulatorWithExistingCharacter(nascentFlins);
        nascentFlins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), nascentSim);
        nascentFlins.onAction(CharacterActionRequest.of(CharacterActionKey.SKILL), nascentSim);
        assertTrue(nascentSim.getTeamBuffList().stream().noneMatch(
                        buff -> buff.getId() == BuffId.FLINS_C2_ELECTRO_RES_SHRED),
                "Flins C2 should not shred at Nascent Gleam");

        model.character.Flins offFieldFlins = new model.character.Flins(
                new TestWeapon(), blankArtifact(), flinsTalentData(2));
        CombatSimulator offFieldSim = simulatorWithExistingCharacter(offFieldFlins);
        offFieldSim.addCharacter(
                testCharacter(Element.HYDRO, CharacterId.XINGQIU));
        offFieldSim.setMoonsign(CombatSimulator.Moonsign.ASCENDANT_GLEAM);
        offFieldSim.setActiveCharacter(CharacterId.XINGQIU);
        offFieldSim.performActionWithoutTimeAdvance(
                CharacterId.FLINS,
                new AttackAction(
                        "Off-field Flins Electro fixture",
                        1.0,
                        Element.ELECTRO,
                        StatType.BASE_ATK));
        assertTrue(offFieldSim.getTeamBuffList().stream().noneMatch(
                        buff -> buff.getId() == BuffId.FLINS_C2_ELECTRO_RES_SHRED),
                "Off-field Flins Electro damage should not apply C2 shred");

        model.character.Flins c3Flins = new model.character.Flins(
                new TestWeapon(), blankArtifact(), flinsTalentData(3));
        CombatSimulator c3Sim = simulatorWithExistingCharacter(c3Flins);
        assertClose(0.0, resolvedStat(c3Sim, c3Flins, StatType.ATK_PERCENT), EPS,
                "Flins C3 should not receive C4 ATK");
        assertClose(352.0 * 0.08,
                resolvedStat(c3Sim, c3Flins, StatType.ELEMENTAL_MASTERY), EPS,
                "Flins C3 Whispering Flame should retain eight percent ATK");

        model.character.Flins c4Flins = new model.character.Flins(
                new TestWeapon(), blankArtifact(), flinsTalentData(4));
        CombatSimulator c4Sim = simulatorWithExistingCharacter(c4Flins);
        assertClose(0.20, resolvedStat(c4Sim, c4Flins, StatType.ATK_PERCENT), EPS,
                "Flins C4 should grant twenty percent ATK");
        assertClose(352.0 * 1.20 * 0.10,
                resolvedStat(c4Sim, c4Flins, StatType.ELEMENTAL_MASTERY), EPS,
                "Flins C4 Whispering Flame should use post-C4 ATK at ten percent");

        StatsContainer belowCapStats = new StatsContainer();
        belowCapStats.add(StatType.ATK_FLAT, 1776.6);
        model.character.Flins belowCapFlins = new model.character.Flins(
                new TestWeapon(),
                new ArtifactSet("Flins C4 below-cap fixture", belowCapStats),
                flinsTalentData(4));
        CombatSimulator belowCapSim = simulatorWithExistingCharacter(belowCapFlins);
        assertClose(219.9,
                resolvedStat(belowCapSim, belowCapFlins, StatType.ELEMENTAL_MASTERY), EPS,
                "Flins C4 should preserve EM immediately below the cap");

        StatsContainer cappedStats = new StatsContainer();
        cappedStats.add(StatType.ATK_FLAT, 1777.6);
        model.character.Flins cappedFlins = new model.character.Flins(
                new TestWeapon(),
                new ArtifactSet("Flins C4 capped fixture", cappedStats),
                flinsTalentData(4));
        CombatSimulator cappedSim = simulatorWithExistingCharacter(cappedFlins);
        assertClose(220.0,
                resolvedStat(cappedSim, cappedFlins, StatType.ELEMENTAL_MASTERY), EPS,
                "Flins C4 Whispering Flame should cap at 220 EM");
    }

    private static Buff requireFlinsC2Shred(CombatSimulator sim) {
        List<Buff> buffs = new ArrayList<>();
        for (Buff buff : sim.getTeamBuffList()) {
            if (buff.getId() == BuffId.FLINS_C2_ELECTRO_RES_SHRED) {
                buffs.add(buff);
            }
        }
        assertEquals(1, buffs.size(),
                "Flins C2 should retain one typed Electro shred");
        assertEquals(CharacterId.FLINS, buffs.get(0).getSourceCharacterId(),
                "Flins C2 shred should retain source ownership");
        return buffs.get(0);
    }

