    private static void testAccuracyPhaseF_FruitOfFulfillment() {
        model.weapon.FruitOfFulfillment fruit =
                new model.weapon.FruitOfFulfillment();
        assertEquals("Fruit of Fulfillment", fruit.getName(),
                "Fruit of Fulfillment display name");
        assertClose(510.0, fruit.getBaseAtk(), EPS,
                "Fruit of Fulfillment base ATK");
        assertClose(0.459,
                fruit.getStats().get(StatType.ENERGY_RECHARGE), EPS,
                "Fruit of Fulfillment Energy Recharge");
        assertEquals(model.type.WeaponType.CATALYST, fruit.getWeaponType(),
                "Fruit of Fulfillment weapon type");
        assertEquals(5, fruit.getRefinement(),
                "Fruit of Fulfillment default refinement");

        TestCharacter fruitAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        TestCharacter fruitOwner = testCharacter(
                Element.DENDRO, CharacterId.SUCROSE);
        fruitOwner.setWeapon(fruit);
        CombatSimulator fruitSim = simulatorWith(fruitAlly);
        fruitSim.addCharacter(fruitOwner);
        ReactionResult overload = ReactionResult.transform(
                0.0, "Overloaded", ReactionResult.Kind.OVERLOAD);
        fruitSim.notifyReaction(ReactionResult.none(), fruitOwner);
        fruitSim.notifyReaction(overload, fruitAlly);
        assertEquals(0, fruit.getStackCount(),
                "NONE and foreign reactions should not add Fruit stacks");
        fruitSim.notifyReaction(overload, fruitOwner);
        fruitSim.notifyReaction(overload, fruitOwner);
        assertEquals(1, fruit.getStackCount(),
                "Fruit should reject a second stack inside 0.3 seconds");
        for (int expectedStack = 2; expectedStack <= 5; expectedStack++) {
            fruitSim.advanceTime(0.3);
            fruitSim.notifyReaction(overload, fruitOwner);
            assertEquals(expectedStack, fruit.getStackCount(),
                    "Fruit stack count at exact 0.3-second boundary");
        }
        assertClose(180.0,
                resolvedStat(fruitSim, fruitOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "R5 Fruit five-stack Elemental Mastery");
        assertClose(-0.25,
                resolvedStat(fruitSim, fruitOwner,
                        StatType.ATK_PERCENT), EPS,
                "Fruit should lose exactly five-percent ATK per stack");
        fruitSim.advanceTime(0.3);
        fruitSim.notifyReaction(overload, fruitOwner);
        assertEquals(5, fruit.getStackCount(),
                "Fruit stacks should cap at five");

        fruitSim.advanceTime(6.0 - 1e-6);
        assertEquals(5, fruit.getStackCount(),
                "Stale decay timers should not reduce refreshed Fruit stacks");
        fruitSim.advanceTime(1e-6 + 1e-9);
        assertEquals(4, fruit.getStackCount(),
                "Fruit should lose one stack at six seconds without reaction");
        fruitSim.advanceTime(24.0);
        assertEquals(0, fruit.getStackCount(),
                "Fruit should decay one stack every six seconds to zero");
        fruitSim.advanceTime(6.0);
        assertEquals(0, fruit.getStackCount(),
                "Fruit decay should remain floored at zero");

        model.weapon.FruitOfFulfillment r1Fruit =
                new model.weapon.FruitOfFulfillment(1);
        TestCharacter r1FruitOwner = testCharacter(Element.DENDRO);
        r1FruitOwner.setWeapon(r1Fruit);
        CombatSimulator r1FruitSim = simulatorWith(r1FruitOwner);
        r1FruitSim.notifyReaction(overload, r1FruitOwner);
        assertClose(24.0,
                resolvedStat(r1FruitSim, r1FruitOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "R1 Fruit one-stack Elemental Mastery");
        assertClose(-0.05,
                resolvedStat(r1FruitSim, r1FruitOwner,
                        StatType.ATK_PERCENT), EPS,
                "R1 Fruit one-stack ATK penalty");

        boolean fruitReuseRejected = false;
        try {
            fruit.initializeForSimulator(fruitOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            fruitReuseRejected = true;
        }
        assertTrue(fruitReuseRejected,
                "Fruit should reject cross-simulator reuse");

        boolean lowFruitRefinementRejected = false;
        try {
            new model.weapon.FruitOfFulfillment(0);
        } catch (IllegalArgumentException expected) {
            lowFruitRefinementRejected = true;
        }
        assertTrue(lowFruitRefinementRejected,
                "Fruit should reject refinement zero");

        boolean highFruitRefinementRejected = false;
        try {
            new model.weapon.FruitOfFulfillment(6);
        } catch (IllegalArgumentException expected) {
            highFruitRefinementRejected = true;
        }
        assertTrue(highFruitRefinementRejected,
                "Fruit should reject refinement six");
    }

    private static void testAccuracyPhaseF_ScionOfTheBlazingSun() {
        model.weapon.ScionOfTheBlazingSun scion =
                new model.weapon.ScionOfTheBlazingSun();
        assertEquals("Scion of the Blazing Sun", scion.getName(),
                "Scion display name");
        assertClose(565.0, scion.getBaseAtk(), EPS,
                "Scion base ATK");
        assertClose(0.184, scion.getStats().get(StatType.CRIT_RATE), EPS,
                "Scion CRIT Rate");
        assertEquals(model.type.WeaponType.BOW, scion.getWeaponType(),
                "Scion weapon type");
        assertEquals(5, scion.getRefinement(),
                "Scion default refinement");

        TestCharacter scionOwner = testCharacter(
                Element.PYRO, CharacterId.SUCROSE);
        scionOwner.setWeapon(scion);
        CombatSimulator scionSim = simulatorWith(scionOwner);
        AttackAction zeroCharge = typedDamageHit(
                "Zero Charged", ActionType.CHARGE, 0.0);
        AttackAction skillHit = typedDamageHit(
                "Skill", ActionType.SKILL, 1.0);
        AttackAction chargedHit = typedDamageHit(
                "Charged", ActionType.CHARGE, 1.0);
        AttackAction generatedProc = typedDamageHit(
                "Scion of the Blazing Sun Sunfire Arrow",
                ActionType.OTHER,
                1.2);
        TestCharacter foreignUser = testCharacter(
                Element.CRYO, CharacterId.KAEYA);

        scion.onDamage(scionOwner, zeroCharge, 0.0, scionSim);
        scion.onDamage(scionOwner, skillHit, 0.0, scionSim);
        scion.onDamage(foreignUser, chargedHit, 0.0, scionSim);
        assertClose(0.0, scionSim.getTotalDamage(), EPS,
                "Zero, wrong-type, and foreign hits should not activate Scion");
        assertClose(0.0,
                resolvedStat(scionSim, scionOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "Rejected Scion hits should not open Heartsearer");

        scion.onDamage(scionOwner, chargedHit, 0.0, scionSim);
        double firstProcDamage = scionSim.getTotalDamage();
        assertTrue(firstProcDamage > 0.0,
                "Scion should resolve its Physical proc immediately");
        assertClose(0.56,
                resolvedStat(scionSim, scionOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "R5 Scion Heartsearer Charged bonus");
        scion.onDamage(scionOwner, generatedProc, 0.0, scionSim);
        assertClose(firstProcDamage, scionSim.getTotalDamage(), EPS,
                "Scion's generated proc should not recurse");

        scionSim.advanceTime(10.0 - 1e-6);
        scion.onDamage(
                scionOwner, chargedHit, scionSim.getCurrentTime(), scionSim);
        assertClose(firstProcDamage, scionSim.getTotalDamage(), EPS,
                "Scion should remain on cooldown before ten seconds");
        assertClose(0.56,
                resolvedStat(scionSim, scionOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "Heartsearer should remain active before ten seconds");
        scionSim.advanceTime(1e-6 + 1e-9);
        assertClose(0.0,
                resolvedStat(scionSim, scionOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "Heartsearer should expire at exactly ten seconds");
        scion.onDamage(
                scionOwner, chargedHit, scionSim.getCurrentTime(), scionSim);
        assertClose(firstProcDamage * 2.0, scionSim.getTotalDamage(), EPS,
                "Scion should reactivate at exact ten-second CT");
        assertClose(0.56,
                resolvedStat(scionSim, scionOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "Exact-CT Scion activation should refresh Heartsearer");

        scionSim.addCharacter(foreignUser);
        scionSim.setActiveCharacter(CharacterId.KAEYA);
        scionSim.advanceTime(10.0);
        scion.onDamage(
                scionOwner, chargedHit, scionSim.getCurrentTime(), scionSim);
        assertClose(firstProcDamage * 2.0, scionSim.getTotalDamage(), EPS,
                "Off-field Charged hits should not activate Scion");
        assertClose(0.0,
                resolvedStat(scionSim, scionOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "Expired Heartsearer should not refresh off-field");

        model.weapon.ScionOfTheBlazingSun r1Scion =
                new model.weapon.ScionOfTheBlazingSun(1);
        TestCharacter r1ScionOwner = testCharacter(
                Element.PYRO, CharacterId.SUCROSE);
        r1ScionOwner.setWeapon(r1Scion);
        CombatSimulator r1ScionSim = simulatorWith(r1ScionOwner);
        r1Scion.onDamage(r1ScionOwner, chargedHit, 0.0, r1ScionSim);
        assertClose(firstProcDamage * 0.5, r1ScionSim.getTotalDamage(), EPS,
                "R1 Scion proc should use 60-percent ATK");
        assertClose(0.28,
                resolvedStat(r1ScionSim, r1ScionOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "R1 Scion Heartsearer Charged bonus");

        boolean scionReuseRejected = false;
        try {
            scion.initializeForSimulator(scionOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            scionReuseRejected = true;
        }
        assertTrue(scionReuseRejected,
                "Scion should reject cross-simulator reuse");

        boolean lowScionRefinementRejected = false;
        try {
            new model.weapon.ScionOfTheBlazingSun(0);
        } catch (IllegalArgumentException expected) {
            lowScionRefinementRejected = true;
        }
        assertTrue(lowScionRefinementRejected,
                "Scion should reject refinement zero");

        boolean highScionRefinementRejected = false;
        try {
            new model.weapon.ScionOfTheBlazingSun(6);
        } catch (IllegalArgumentException expected) {
            highScionRefinementRejected = true;
        }
        assertTrue(highScionRefinementRejected,
                "Scion should reject refinement six");
    }

    private static void testAccuracyPhaseF_AlleyHunter() {
        model.weapon.AlleyHunter alleyHunter =
                new model.weapon.AlleyHunter();
        assertEquals("Alley Hunter", alleyHunter.getName(),
                "Alley Hunter display name");
        assertClose(565.0, alleyHunter.getBaseAtk(), EPS,
                "Alley Hunter base ATK");
        assertClose(0.276,
                alleyHunter.getStats().get(StatType.ATK_PERCENT), EPS,
                "Alley Hunter ATK substat");
        assertEquals(model.type.WeaponType.BOW, alleyHunter.getWeaponType(),
                "Alley Hunter weapon type");
        assertEquals(5, alleyHunter.getRefinement(),
                "Alley Hunter default refinement");

        TestCharacter activeAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        TestCharacter alleyOwner = testCharacter(
                Element.CRYO, CharacterId.KAEYA);
        alleyOwner.setWeapon(alleyHunter);
        CombatSimulator alleySim = simulatorWith(activeAlly);
        alleySim.addCharacter(alleyOwner);
        alleySim.advanceTime(1.0 - 1e-6);
        assertClose(0.0,
                resolvedStat(alleySim, alleyOwner, StatType.DMG_BONUS_ALL), EPS,
                "Alley Hunter should wait for its exact first tick");
        alleySim.advanceTime(1e-6 + 1e-9);
        assertEquals(1, alleyHunter.getStackCount(),
                "Alley Hunter first off-field stack at one second");
        assertClose(0.04,
                resolvedStat(alleySim, alleyOwner, StatType.DMG_BONUS_ALL), EPS,
                "R5 Alley Hunter first off-field bonus");
        alleySim.advanceTime(9.0);
        assertEquals(10, alleyHunter.getStackCount(),
                "Alley Hunter should reach ten stacks");
        assertClose(0.40,
                resolvedStat(alleySim, alleyOwner, StatType.DMG_BONUS_ALL), EPS,
                "R5 Alley Hunter capped off-field bonus");
        alleySim.advanceTime(1.0);
        assertEquals(10, alleyHunter.getStackCount(),
                "Alley Hunter should remain capped off-field");

        alleySim.setActiveCharacter(CharacterId.KAEYA);
        alleySim.advanceTime(4.0);
        assertClose(0.40,
                resolvedStat(alleySim, alleyOwner, StatType.DMG_BONUS_ALL), EPS,
                "Alley Hunter should retain its bonus for four active seconds");
        alleySim.advanceTime(1.0);
        assertEquals(8, alleyHunter.getStackCount(),
                "Alley Hunter should remove two stacks after the grace period");
        assertClose(0.32,
                resolvedStat(alleySim, alleyOwner, StatType.DMG_BONUS_ALL), EPS,
                "R5 Alley Hunter first on-field decay tick");

        alleySim.setActiveCharacter(CharacterId.AMBER);
        alleySim.advanceTime(1.0);
        assertEquals(9, alleyHunter.getStackCount(),
                "Returning off-field should grow and reset the active grace");
        alleySim.setActiveCharacter(CharacterId.KAEYA);
        alleySim.advanceTime(4.0);
        assertEquals(9, alleyHunter.getStackCount(),
                "Reset Alley Hunter grace should retain stacks for four ticks");
        alleySim.advanceTime(5.0);
        assertEquals(0, alleyHunter.getStackCount(),
                "Alley Hunter decay should floor at zero");

        model.weapon.AlleyHunter r1AlleyHunter =
                new model.weapon.AlleyHunter(1);
        TestCharacter r1ActiveAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        TestCharacter r1AlleyOwner = testCharacter(
                Element.CRYO, CharacterId.KAEYA);
        r1AlleyOwner.setWeapon(r1AlleyHunter);
        CombatSimulator r1AlleySim = simulatorWith(r1ActiveAlly);
        r1AlleySim.addCharacter(r1AlleyOwner);
        r1AlleySim.advanceTime(10.0);
        assertClose(0.20,
                resolvedStat(r1AlleySim, r1AlleyOwner,
                        StatType.DMG_BONUS_ALL), EPS,
                "R1 Alley Hunter capped off-field bonus");
        r1AlleySim.setActiveCharacter(CharacterId.KAEYA);
        r1AlleySim.advanceTime(5.0);
        assertClose(0.16,
                resolvedStat(r1AlleySim, r1AlleyOwner,
                        StatType.DMG_BONUS_ALL), EPS,
                "R1 Alley Hunter first decay should remove four percent");

        boolean alleyReuseRejected = false;
        try {
            alleyHunter.initializeForSimulator(alleyOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            alleyReuseRejected = true;
        }
        assertTrue(alleyReuseRejected,
                "Alley Hunter should reject cross-simulator reuse");

        boolean lowAlleyRefinementRejected = false;
        try {
            new model.weapon.AlleyHunter(0);
        } catch (IllegalArgumentException expected) {
            lowAlleyRefinementRejected = true;
        }
        assertTrue(lowAlleyRefinementRejected,
                "Alley Hunter should reject refinement zero");

        boolean highAlleyRefinementRejected = false;
        try {
            new model.weapon.AlleyHunter(6);
        } catch (IllegalArgumentException expected) {
            highAlleyRefinementRejected = true;
        }
        assertTrue(highAlleyRefinementRejected,
                "Alley Hunter should reject refinement six");
    }

