    private static void testAccuracyPhaseF_ThreeStarRuntimeBoundaryPhaseTwo() {
        model.weapon.BoundaryInactiveWeapon[] weapons = {
            new model.weapon.TravelersHandySword(),
            new model.weapon.WhiteIronGreatsword(),
            new model.weapon.BlackTassel(),
            new model.weapon.Messenger(),
            new model.weapon.RecurveBow(),
            new model.weapon.SharpshootersOath(),
            new model.weapon.OtherworldlyStory(),
            new model.weapon.TwinNephrite()
        };
        String[] names = {
            "Traveler's Handy Sword",
            "White Iron Greatsword",
            "Black Tassel",
            "Messenger",
            "Recurve Bow",
            "Sharpshooter's Oath",
            "Otherworldly Story",
            "Twin Nephrite"
        };
        model.type.WeaponType[] weaponTypes = {
            model.type.WeaponType.SWORD,
            model.type.WeaponType.CLAYMORE,
            model.type.WeaponType.POLEARM,
            model.type.WeaponType.BOW,
            model.type.WeaponType.BOW,
            model.type.WeaponType.BOW,
            model.type.WeaponType.CATALYST,
            model.type.WeaponType.CATALYST
        };
        double[] baseAttack = {
            448.0, 401.0, 354.0, 448.0, 354.0, 401.0, 401.0, 448.0
        };
        StatType[] secondaryTypes = {
            StatType.DEF_PERCENT,
            StatType.DEF_PERCENT,
            StatType.HP_PERCENT,
            StatType.CRIT_DMG,
            StatType.HP_PERCENT,
            StatType.CRIT_DMG,
            StatType.ENERGY_RECHARGE,
            StatType.CRIT_RATE
        };
        double[] secondaryValues = {
            0.293, 0.439, 0.469, 0.312, 0.469, 0.469, 0.390, 0.156
        };
        List<java.util.function.IntFunction<model.weapon.BoundaryInactiveWeapon>>
                factories = List.of(
                        model.weapon.TravelersHandySword::new,
                        model.weapon.WhiteIronGreatsword::new,
                        model.weapon.BlackTassel::new,
                        model.weapon.Messenger::new,
                        model.weapon.RecurveBow::new,
                        model.weapon.SharpshootersOath::new,
                        model.weapon.OtherworldlyStory::new,
                        model.weapon.TwinNephrite::new);

        for (int index = 0; index < weapons.length; index++) {
            model.weapon.BoundaryInactiveWeapon weapon = weapons[index];
            assertEquals(names[index], weapon.getName(),
                    names[index] + " display name");
            assertEquals(weaponTypes[index], weapon.getWeaponType(),
                    names[index] + " weapon type");
            assertClose(baseAttack[index], weapon.getBaseAtk(), EPS,
                    names[index] + " base ATK");
            assertClose(secondaryValues[index],
                    weapon.getStats().get(secondaryTypes[index]), EPS,
                    names[index] + " secondary stat");
            assertEquals(5, weapon.getRefinement(),
                    names[index] + " default refinement");

            StatsContainer passiveStats = new StatsContainer();
            passiveStats.set(StatType.ATK_PERCENT, 0.25);
            weapon.applyPassive(passiveStats, -1.0);
            weapon.applyPassive(passiveStats, 100.0);
            assertClose(0.25,
                    passiveStats.get(StatType.ATK_PERCENT), EPS,
                    names[index] + " should not fabricate unavailable state");

            model.weapon.BoundaryInactiveWeapon r1Weapon =
                    factories.get(index).apply(1);
            assertEquals(1, r1Weapon.getRefinement(),
                    names[index] + " selected R1");
            boolean lowRefinementRejected = false;
            try {
                factories.get(index).apply(0);
            } catch (IllegalArgumentException expected) {
                lowRefinementRejected = true;
            }
            assertTrue(lowRefinementRejected,
                    names[index] + " should reject refinement zero");
            boolean highRefinementRejected = false;
            try {
                factories.get(index).apply(6);
            } catch (IllegalArgumentException expected) {
                highRefinementRejected = true;
            }
            assertTrue(highRefinementRejected,
                    names[index] + " should reject refinement six");
        }

        model.weapon.Slingshot slingshot = new model.weapon.Slingshot();
        assertEquals("Slingshot", slingshot.getName(),
                "Slingshot display name");
        assertClose(354.0, slingshot.getBaseAtk(), EPS,
                "Slingshot base ATK");
        assertClose(0.312,
                slingshot.getStats().get(StatType.CRIT_RATE), EPS,
                "Slingshot CRIT Rate");
        assertEquals(model.type.WeaponType.BOW,
                slingshot.getWeaponType(), "Slingshot weapon type");
        assertEquals(5, slingshot.getRefinement(),
                "Slingshot default refinement");
        StatsContainer slingshotStats = new StatsContainer();
        slingshot.applyPassive(slingshotStats, -1.0);
        assertClose(0.60,
                slingshotStats.get(StatType.NORMAL_ATTACK_DMG_BONUS), EPS,
                "R5 Slingshot immediate Normal bonus");
        assertClose(0.60,
                slingshotStats.get(StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "R5 Slingshot immediate Charged bonus");
        assertClose(0.0,
                slingshotStats.get(StatType.SKILL_DMG_BONUS), EPS,
                "Slingshot should not buff Skill damage");
        assertClose(0.0,
                slingshotStats.get(StatType.BURST_DMG_BONUS), EPS,
                "Slingshot should not buff Burst damage");
        model.weapon.Slingshot r1Slingshot =
                new model.weapon.Slingshot(1);
        StatsContainer r1SlingshotStats = new StatsContainer();
        r1Slingshot.applyPassive(r1SlingshotStats, 100.0);
        assertClose(0.36,
                r1SlingshotStats.get(StatType.NORMAL_ATTACK_DMG_BONUS), EPS,
                "R1 Slingshot immediate Normal bonus");
        assertClose(0.36,
                r1SlingshotStats.get(StatType.CHARGED_ATTACK_DMG_BONUS), EPS,
                "R1 Slingshot immediate Charged bonus");

        boolean lowSlingshotRefinementRejected = false;
        try {
            new model.weapon.Slingshot(0);
        } catch (IllegalArgumentException expected) {
            lowSlingshotRefinementRejected = true;
        }
        assertTrue(lowSlingshotRefinementRejected,
                "Slingshot should reject refinement zero");
        boolean highSlingshotRefinementRejected = false;
        try {
            new model.weapon.Slingshot(6);
        } catch (IllegalArgumentException expected) {
            highSlingshotRefinementRejected = true;
        }
        assertTrue(highSlingshotRefinementRejected,
                "Slingshot should reject refinement six");
    }

    private static void testAccuracyPhaseF_StatefulCraftableWeaponPhaseOne() {
        model.weapon.RingOfYaxche ring = new model.weapon.RingOfYaxche();
        assertEquals("Ring of Yaxche", ring.getName(),
                "Ring of Yaxche display name");
        assertEquals(model.type.WeaponType.CATALYST, ring.getWeaponType(),
                "Ring of Yaxche weapon type");
        assertClose(510.0, ring.getBaseAtk(), EPS,
                "Ring of Yaxche base ATK");
        assertClose(0.413, ring.getStats().get(StatType.HP_PERCENT), EPS,
                "Ring of Yaxche HP percent");
        assertEquals(5, ring.getRefinement(),
                "Ring of Yaxche default refinement");

        TestCharacter ringOwner = testCharacter(
                Element.HYDRO, CharacterId.SUCROSE);
        ringOwner.setWeapon(ring);
        CombatSimulator ringSim = simulatorWith(ringOwner);
        ring.onAction(
                ringOwner,
                CharacterActionRequest.of(CharacterActionKey.NORMAL),
                ringSim);
        assertClose(0.0,
                effectiveStatAt(ringOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS, 0.0), EPS,
                "Ring of Yaxche should reject non-Skill actions");
        ring.onAction(
                ringOwner,
                CharacterActionRequest.of(CharacterActionKey.SKILL),
                ringSim);
        assertClose(0.14,
                effectiveStatAt(ringOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS, 0.0), EPS,
                "R5 Ring of Yaxche should quantize 14,130 Max HP");
        assertClose(0.0,
                effectiveStatAt(ringOwner,
                        StatType.CHARGED_ATTACK_DMG_BONUS, 0.0), EPS,
                "Ring of Yaxche should only buff Normal Attack damage");
        ringSim.advanceTime(9.0);
        ringOwner.withStat(StatType.BASE_HP, 20000.0);
        ring.onAction(
                ringOwner,
                CharacterActionRequest.of(CharacterActionKey.SKILL),
                ringSim);
        assertClose(0.28,
                effectiveStatAt(ringOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS, 10.0), EPS,
                "Ring of Yaxche should refresh and resnapshot Max HP");
        assertClose(0.0,
                effectiveStatAt(ringOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS, 19.0), EPS,
                "Ring of Yaxche should expire at exactly ten seconds");

        model.weapon.RingOfYaxche cappedRing =
                new model.weapon.RingOfYaxche(5);
        TestCharacter cappedRingOwner = testCharacter(
                Element.HYDRO, CharacterId.SUCROSE)
                .withStat(StatType.BASE_HP, 50000.0);
        cappedRingOwner.setWeapon(cappedRing);
        CombatSimulator cappedRingSim = simulatorWith(cappedRingOwner);
        cappedRing.onAction(
                cappedRingOwner,
                CharacterActionRequest.of(CharacterActionKey.SKILL),
                cappedRingSim);
        assertClose(0.32,
                effectiveStatAt(cappedRingOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS, 0.0), EPS,
                "R5 Ring of Yaxche should cap its Normal bonus");

        model.weapon.RingOfYaxche r1Ring =
                new model.weapon.RingOfYaxche(1);
        TestCharacter r1RingOwner = testCharacter(
                Element.HYDRO, CharacterId.SUCROSE);
        r1RingOwner.setWeapon(r1Ring);
        CombatSimulator r1RingSim = simulatorWith(r1RingOwner);
        r1Ring.onAction(
                r1RingOwner,
                CharacterActionRequest.of(CharacterActionKey.SKILL),
                r1RingSim);
        assertClose(0.084,
                effectiveStatAt(r1RingOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS, 0.0), EPS,
                "R1 Ring of Yaxche quantized Normal bonus");

        TestCharacter foreignUser = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        r1Ring.onAction(
                foreignUser,
                CharacterActionRequest.of(CharacterActionKey.SKILL),
                r1RingSim);
        r1Ring.onAction(
                r1RingOwner,
                CharacterActionRequest.of(CharacterActionKey.SKILL),
                new CombatSimulator());
        r1Ring.initializeForSimulator(r1RingOwner, r1RingSim);
        boolean ringReuseRejected = false;
        try {
            r1Ring.initializeForSimulator(r1RingOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            ringReuseRejected = true;
        }
        assertTrue(ringReuseRejected,
                "Ring of Yaxche should reject cross-simulator reuse");

        model.weapon.Cloudforged cloudforged =
                new model.weapon.Cloudforged();
        assertEquals("Cloudforged", cloudforged.getName(),
                "Cloudforged display name");
        assertEquals(model.type.WeaponType.BOW, cloudforged.getWeaponType(),
                "Cloudforged weapon type");
        assertClose(510.0, cloudforged.getBaseAtk(), EPS,
                "Cloudforged base ATK");
        assertClose(165.0,
                cloudforged.getStats().get(StatType.ELEMENTAL_MASTERY), EPS,
                "Cloudforged Elemental Mastery");
        assertEquals(5, cloudforged.getRefinement(),
                "Cloudforged default refinement");

        TestCharacter cloudOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        cloudOwner.setWeapon(cloudforged);
        CombatSimulator cloudSim = simulatorWith(cloudOwner);
        cloudforged.onAction(
                cloudOwner,
                CharacterActionRequest.of(CharacterActionKey.SKILL),
                cloudSim);
        assertClose(165.0,
                effectiveStatAt(cloudOwner,
                        StatType.ELEMENTAL_MASTERY, 0.0), EPS,
                "Cloudforged should reject non-Burst actions");
        cloudforged.onAction(
                cloudOwner,
                CharacterActionRequest.of(CharacterActionKey.BURST),
                cloudSim);
        assertClose(245.0,
                effectiveStatAt(cloudOwner,
                        StatType.ELEMENTAL_MASTERY, 0.0), EPS,
                "R5 Cloudforged first stack");
        cloudforged.onAction(
                cloudOwner,
                CharacterActionRequest.of(CharacterActionKey.BURST),
                cloudSim);
        assertClose(325.0,
                effectiveStatAt(cloudOwner,
                        StatType.ELEMENTAL_MASTERY, 0.0), EPS,
                "R5 Cloudforged second stack");
        cloudSim.advanceTime(17.0);
        cloudforged.onAction(
                cloudOwner,
                CharacterActionRequest.of(CharacterActionKey.BURST),
                cloudSim);
        assertClose(325.0,
                effectiveStatAt(cloudOwner,
                        StatType.ELEMENTAL_MASTERY, 18.0), EPS,
                "Cloudforged stack gain should refresh both stacks");
        assertClose(165.0,
                effectiveStatAt(cloudOwner,
                        StatType.ELEMENTAL_MASTERY, 35.0), EPS,
                "Cloudforged should expire at exactly eighteen seconds");

        model.weapon.Cloudforged r1Cloudforged =
                new model.weapon.Cloudforged(1);
        TestCharacter r1CloudOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        r1CloudOwner.setWeapon(r1Cloudforged);
        CombatSimulator r1CloudSim = simulatorWith(r1CloudOwner);
        r1Cloudforged.onAction(
                r1CloudOwner,
                CharacterActionRequest.of(CharacterActionKey.BURST),
                r1CloudSim);
        assertClose(205.0,
                effectiveStatAt(r1CloudOwner,
                        StatType.ELEMENTAL_MASTERY, 0.0), EPS,
                "R1 Cloudforged first stack");
        r1Cloudforged.onAction(
                foreignUser,
                CharacterActionRequest.of(CharacterActionKey.BURST),
                r1CloudSim);
        r1Cloudforged.onAction(
                r1CloudOwner,
                CharacterActionRequest.of(CharacterActionKey.BURST),
                new CombatSimulator());
        assertClose(205.0,
                effectiveStatAt(r1CloudOwner,
                        StatType.ELEMENTAL_MASTERY, 0.0), EPS,
                "Cloudforged should reject foreign dispatch");
        r1Cloudforged.initializeForSimulator(r1CloudOwner, r1CloudSim);
        boolean cloudReuseRejected = false;
        try {
            r1Cloudforged.initializeForSimulator(
                    r1CloudOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            cloudReuseRejected = true;
        }
        assertTrue(cloudReuseRejected,
                "Cloudforged should reject cross-simulator reuse");

        boolean lowRingRefinementRejected = false;
        try {
            new model.weapon.RingOfYaxche(0);
        } catch (IllegalArgumentException expected) {
            lowRingRefinementRejected = true;
        }
        assertTrue(lowRingRefinementRejected,
                "Ring of Yaxche should reject refinement zero");
        boolean highRingRefinementRejected = false;
        try {
            new model.weapon.RingOfYaxche(6);
        } catch (IllegalArgumentException expected) {
            highRingRefinementRejected = true;
        }
        assertTrue(highRingRefinementRejected,
                "Ring of Yaxche should reject refinement six");
        boolean lowCloudRefinementRejected = false;
        try {
            new model.weapon.Cloudforged(0);
        } catch (IllegalArgumentException expected) {
            lowCloudRefinementRejected = true;
        }
        assertTrue(lowCloudRefinementRejected,
                "Cloudforged should reject refinement zero");
        boolean highCloudRefinementRejected = false;
        try {
            new model.weapon.Cloudforged(6);
        } catch (IllegalArgumentException expected) {
            highCloudRefinementRejected = true;
        }
        assertTrue(highCloudRefinementRejected,
                "Cloudforged should reject refinement six");
    }

    private static void testAccuracyPhaseF_StatefulCraftableWeaponPhaseTwo() {
        model.weapon.HakushinRing hakushin =
                new model.weapon.HakushinRing();
        assertEquals("Hakushin Ring", hakushin.getName(),
                "Hakushin Ring display name");
        assertEquals(model.type.WeaponType.CATALYST,
                hakushin.getWeaponType(), "Hakushin Ring weapon type");
        assertClose(565.0, hakushin.getBaseAtk(), EPS,
                "Hakushin Ring base ATK");
        assertClose(0.306,
                hakushin.getStats().get(StatType.ENERGY_RECHARGE), EPS,
                "Hakushin Ring Energy Recharge");
        assertEquals(5, hakushin.getRefinement(),
                "Hakushin Ring default refinement");

        TestCharacter electroOwner = testCharacter(
                Element.ELECTRO, CharacterId.SUCROSE);
        electroOwner.setWeapon(hakushin);
        TestCharacter pyroAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        TestCharacter hydroAlly = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        CombatSimulator hakushinSim = simulatorWith(electroOwner);
        hakushinSim.addCharacter(pyroAlly);
        hakushinSim.addCharacter(hydroAlly);
        hakushinSim.notifyReaction(ReactionResult.transform(
                0.0, "Overloaded", ReactionResult.Kind.OVERLOADED),
                electroOwner);
        assertClose(0.20,
                resolvedStat(hakushinSim, electroOwner,
                        StatType.ELECTRO_DMG_BONUS), EPS,
                "R5 Hakushin should include its Electro holder");
        assertClose(0.20,
                resolvedStat(hakushinSim, pyroAlly,
                        StatType.PYRO_DMG_BONUS), EPS,
                "R5 Hakushin should buff involved Pyro members");
        assertClose(0.0,
                resolvedStat(hakushinSim, hydroAlly,
                        StatType.HYDRO_DMG_BONUS), EPS,
                "Hakushin should exclude uninvolved elements");

        hakushinSim.advanceTime(3.0);
        hakushinSim.notifyReaction(ReactionResult.transform(
                0.0,
                "Electro-Charged",
                ReactionResult.Kind.ELECTRO_CHARGED), electroOwner);
        hakushinSim.advanceTime(3.0);
        assertClose(0.0,
                resolvedStat(hakushinSim, electroOwner,
                        StatType.ELECTRO_DMG_BONUS), EPS,
                "Hakushin should not refresh an active Electro window");
        assertClose(0.0,
                resolvedStat(hakushinSim, pyroAlly,
                        StatType.PYRO_DMG_BONUS), EPS,
                "Hakushin Pyro window should expire at exactly six seconds");
        assertClose(0.20,
                resolvedStat(hakushinSim, hydroAlly,
                        StatType.HYDRO_DMG_BONUS), EPS,
                "A newly involved Hakushin element should keep its own window");
        hakushinSim.advanceTime(3.0);
        assertClose(0.0,
                resolvedStat(hakushinSim, hydroAlly,
                        StatType.HYDRO_DMG_BONUS), EPS,
                "Hakushin Hydro window should expire at exactly six seconds");

        model.weapon.HakushinRing hyperbloomHakushin =
                new model.weapon.HakushinRing();
        TestCharacter hyperbloomOwner = testCharacter(
                Element.ELECTRO, CharacterId.SUCROSE);
        hyperbloomOwner.setWeapon(hyperbloomHakushin);
        TestCharacter dendroAlly = testCharacter(
                Element.DENDRO, CharacterId.KAEYA);
        TestCharacter excludedHydroAlly = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        CombatSimulator hyperbloomSim = simulatorWith(hyperbloomOwner);
        hyperbloomSim.addCharacter(dendroAlly);
        hyperbloomSim.addCharacter(excludedHydroAlly);
        hyperbloomSim.notifyReaction(ReactionResult.transform(
                0.0, "Hyperbloom", ReactionResult.Kind.HYPERBLOOM),
                hyperbloomOwner);
        assertClose(0.20,
                resolvedStat(hyperbloomSim, dendroAlly,
                        StatType.DENDRO_DMG_BONUS), EPS,
                "Hakushin Hyperbloom should include Dendro");
        assertClose(0.0,
                resolvedStat(hyperbloomSim, excludedHydroAlly,
                        StatType.HYDRO_DMG_BONUS), EPS,
                "Hakushin Hyperbloom should exclude Hydro");

        model.weapon.HakushinRing r1Hakushin =
                new model.weapon.HakushinRing(1);
        TestCharacter anemoOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        anemoOwner.setWeapon(r1Hakushin);
        TestCharacter electroAlly = testCharacter(
                Element.ELECTRO, CharacterId.RAIDEN_SHOGUN);
        CombatSimulator swirlSim = simulatorWith(anemoOwner);
        swirlSim.addCharacter(electroAlly);
        swirlSim.notifyReaction(ReactionResult.transform(
                0.0,
                "Pyro Swirl",
                ReactionResult.Kind.SWIRL,
                Element.PYRO), anemoOwner);
        assertClose(0.0,
                resolvedStat(swirlSim, anemoOwner,
                        StatType.ANEMO_DMG_BONUS), EPS,
                "Hakushin should reject non-Electro Swirl");
        swirlSim.notifyReaction(ReactionResult.transform(
                0.0,
                "Electro Swirl",
                ReactionResult.Kind.SWIRL,
                Element.ELECTRO), anemoOwner);
        assertClose(0.10,
                resolvedStat(swirlSim, anemoOwner,
                        StatType.ANEMO_DMG_BONUS), EPS,
                "R1 Hakushin Electro Swirl should include Anemo holder");
        assertClose(0.10,
                resolvedStat(swirlSim, electroAlly,
                        StatType.ELECTRO_DMG_BONUS), EPS,
                "R1 Hakushin Electro Swirl should include Electro allies");

        model.weapon.HakushinRing offFieldHakushin =
                new model.weapon.HakushinRing();
        TestCharacter offFieldOwner = testCharacter(
                Element.ELECTRO, CharacterId.SUCROSE);
        offFieldOwner.setWeapon(offFieldHakushin);
        TestCharacter activePyro = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        CombatSimulator offFieldHakushinSim = simulatorWith(offFieldOwner);
        offFieldHakushinSim.addCharacter(activePyro);
        offFieldHakushinSim.setActiveCharacter(CharacterId.AMBER);
        offFieldHakushinSim.notifyReaction(ReactionResult.transform(
                0.0, "Overloaded", ReactionResult.Kind.OVERLOADED),
                offFieldOwner);
        assertClose(0.0,
                resolvedStat(offFieldHakushinSim, activePyro,
                        StatType.PYRO_DMG_BONUS), EPS,
                "Hakushin should reject off-field owner reactions");
        offFieldHakushin.initializeForSimulator(
                offFieldOwner, offFieldHakushinSim);
        boolean hakushinReuseRejected = false;
        try {
            offFieldHakushin.initializeForSimulator(
                    offFieldOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            hakushinReuseRejected = true;
        }
        assertTrue(hakushinReuseRejected,
                "Hakushin Ring should reject cross-simulator reuse");

        model.weapon.CrescentPike crescentPike =
                new model.weapon.CrescentPike();
        assertEquals("Crescent Pike", crescentPike.getName(),
                "Crescent Pike display name");
        assertEquals(model.type.WeaponType.POLEARM,
                crescentPike.getWeaponType(), "Crescent Pike weapon type");
        assertClose(565.0, crescentPike.getBaseAtk(), EPS,
                "Crescent Pike base ATK");
        assertClose(0.345,
                crescentPike.getStats().get(StatType.PHYSICAL_DMG_BONUS), EPS,
                "Crescent Pike Physical DMG Bonus");
        assertEquals(5, crescentPike.getRefinement(),
                "Crescent Pike default refinement");

        TestCharacter pikeOwner = testCharacter(
                Element.PHYSICAL, CharacterId.SUCROSE);
        pikeOwner.setWeapon(crescentPike);
        CombatSimulator pikeSim = simulatorWith(pikeOwner);
        List<AttackAction> pikeDamageActions = new ArrayList<>();
        pikeSim.addDamageListener((actor, action, damage, time) ->
                pikeDamageActions.add(action));
        pikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("Pike pre-particle Normal", ActionType.NORMAL, 1.0));
        assertEquals(0,
                countNamedActions(pikeDamageActions,
                        "Crescent Pike Infusion Needle"),
                "Crescent Pike should require particle collection");

        pikeDamageActions.clear();
        pikeSim.notifyParticle(Element.PYRO, 1.0);
        pikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("Pike active Normal", ActionType.NORMAL, 1.0));
        assertEquals(1,
                countNamedActions(pikeDamageActions,
                        "Crescent Pike Infusion Needle"),
                "Crescent Pike should add one hit to a Normal Attack");
        AttackAction r5PikeProc = findAction(
                pikeDamageActions, "Crescent Pike Infusion Needle");
        assertClose(0.40, r5PikeProc.getDamagePercent(), EPS,
                "R5 Crescent Pike follow-up motion value");
        assertEquals(Element.PHYSICAL, r5PikeProc.getElement(),
                "Crescent Pike follow-up element");
        assertEquals(ActionType.OTHER, r5PikeProc.getActionType(),
                "Crescent Pike follow-up action type");

        pikeDamageActions.clear();
        pikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("Pike active Charged", ActionType.CHARGE, 1.0));
        assertEquals(1,
                countNamedActions(pikeDamageActions,
                        "Crescent Pike Infusion Needle"),
                "Crescent Pike should add one hit to a Charged Attack");
        pikeDamageActions.clear();
        pikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("Pike active Skill", ActionType.SKILL, 1.0));
        pikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("Pike zero Normal", ActionType.NORMAL, 0.0));
        assertEquals(0,
                countNamedActions(pikeDamageActions,
                        "Crescent Pike Infusion Needle"),
                "Crescent Pike should reject Skill and zero-MV damage");
        pikeSim.advanceTime(5.0);
        pikeDamageActions.clear();
        pikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("Pike expired Normal", ActionType.NORMAL, 1.0));
        assertEquals(0,
                countNamedActions(pikeDamageActions,
                        "Crescent Pike Infusion Needle"),
                "Crescent Pike should expire at exactly five seconds");

        model.weapon.CrescentPike r1Pike =
                new model.weapon.CrescentPike(1);
        TestCharacter r1PikeOwner = testCharacter(
                Element.PHYSICAL, CharacterId.SUCROSE);
        r1PikeOwner.setWeapon(r1Pike);
        CombatSimulator r1PikeSim = simulatorWith(r1PikeOwner);
        List<AttackAction> r1PikeActions = new ArrayList<>();
        r1PikeSim.addDamageListener((actor, action, damage, time) ->
                r1PikeActions.add(action));
        r1PikeSim.notifyParticle(Element.PHYSICAL, 1.0);
        r1PikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("R1 Pike Normal", ActionType.NORMAL, 1.0));
        assertClose(0.20,
                findAction(r1PikeActions,
                        "Crescent Pike Infusion Needle").getDamagePercent(),
                EPS, "R1 Crescent Pike follow-up motion value");
        r1Pike.initializeForSimulator(r1PikeOwner, r1PikeSim);
        boolean pikeReuseRejected = false;
        try {
            r1Pike.initializeForSimulator(r1PikeOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            pikeReuseRejected = true;
        }
        assertTrue(pikeReuseRejected,
                "Crescent Pike should reject cross-simulator reuse");

        model.weapon.CrescentPike offFieldPike =
                new model.weapon.CrescentPike();
        TestCharacter offFieldPikeOwner = testCharacter(
                Element.PHYSICAL, CharacterId.SUCROSE);
        offFieldPikeOwner.setWeapon(offFieldPike);
        TestCharacter particleCollector = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        CombatSimulator offFieldPikeSim = simulatorWith(offFieldPikeOwner);
        offFieldPikeSim.addCharacter(particleCollector);
        offFieldPikeSim.setActiveCharacter(CharacterId.AMBER);
        offFieldPikeSim.notifyParticle(Element.PYRO, 1.0);
        offFieldPikeSim.setActiveCharacter(CharacterId.SUCROSE);
        List<AttackAction> offFieldPikeActions = new ArrayList<>();
        offFieldPikeSim.addDamageListener((actor, action, damage, time) ->
                offFieldPikeActions.add(action));
        offFieldPikeSim.performActionWithoutTimeAdvance(
                CharacterId.SUCROSE,
                typedDamageHit("Off-field particle Normal", ActionType.NORMAL, 1.0));
        assertEquals(0,
                countNamedActions(offFieldPikeActions,
                        "Crescent Pike Infusion Needle"),
                "Crescent Pike should reject particles collected off-field");

        boolean lowHakushinRefinementRejected = false;
        try {
            new model.weapon.HakushinRing(0);
        } catch (IllegalArgumentException expected) {
            lowHakushinRefinementRejected = true;
        }
        assertTrue(lowHakushinRefinementRejected,
                "Hakushin Ring should reject refinement zero");
        boolean highHakushinRefinementRejected = false;
        try {
            new model.weapon.HakushinRing(6);
        } catch (IllegalArgumentException expected) {
            highHakushinRefinementRejected = true;
        }
        assertTrue(highHakushinRefinementRejected,
                "Hakushin Ring should reject refinement six");
        boolean lowPikeRefinementRejected = false;
        try {
            new model.weapon.CrescentPike(0);
        } catch (IllegalArgumentException expected) {
            lowPikeRefinementRejected = true;
        }
        assertTrue(lowPikeRefinementRejected,
                "Crescent Pike should reject refinement zero");
        boolean highPikeRefinementRejected = false;
        try {
            new model.weapon.CrescentPike(6);
        } catch (IllegalArgumentException expected) {
            highPikeRefinementRejected = true;
        }
        assertTrue(highPikeRefinementRejected,
                "Crescent Pike should reject refinement six");
    }

    private static void testAccuracyPhaseF_WeaponSwitchCallbackContract() {
        LegacySwitchRecordingWeapon legacyWeapon =
                new LegacySwitchRecordingWeapon();
        TestCharacter legacyOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        legacyOwner.setWeapon(legacyWeapon);
        ModernSwitchRecordingWeapon modernWeapon =
                new ModernSwitchRecordingWeapon();
        TestCharacter modernOwner = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        modernOwner.setWeapon(modernWeapon);
        CombatSimulator sim = simulatorWith(legacyOwner);
        sim.addCharacter(modernOwner);

        sim.switchCharacter(CharacterId.AMBER);
        assertEquals(1, legacyWeapon.outgoingCount,
                "Legacy switch callback should remain compatible");
        assertEquals(CharacterId.SUCROSE,
                legacyWeapon.activeCharacterAtOutgoing,
                "Outgoing callback should run before the party switch");
        assertEquals(1, modernWeapon.incomingCount,
                "Incoming weapon should receive one switch callback");
        assertEquals(CharacterId.AMBER,
                modernWeapon.activeCharacterAtIncoming,
                "Incoming callback should run after the party switch");
        assertClose(0.0, legacyWeapon.outgoingTime, EPS,
                "Outgoing callback should run before swap delay");
        assertClose(0.0, modernWeapon.incomingTime, EPS,
                "Incoming callback should run before swap delay");

        sim.switchCharacter(CharacterId.SUCROSE);
        assertEquals(1, modernWeapon.targetOutgoingCount,
                "Modern outgoing callback should run exactly once");
        assertEquals(1, modernWeapon.legacyOutgoingCount,
                "Modern callback should deliberately retain legacy behavior once");
        assertEquals(CharacterId.SUCROSE,
                modernWeapon.incomingTargetId,
                "Outgoing weapon should receive the resolved incoming target");
        assertEquals(CharacterId.AMBER,
                modernWeapon.activeCharacterAtOutgoing,
                "Modern outgoing callback should observe the old active owner");

        int callbacksBeforeMissingTarget = legacyWeapon.outgoingCount
                + modernWeapon.incomingCount
                + modernWeapon.targetOutgoingCount;
        double timeBeforeMissingTarget = sim.getCurrentTime();
        sim.switchCharacter(CharacterId.FLINS);
        assertEquals(CharacterId.SUCROSE,
                sim.getActiveCharacter().getCharacterId(),
                "Missing switch target should preserve active character");
        assertClose(timeBeforeMissingTarget, sim.getCurrentTime(), EPS,
                "Missing switch target should not consume cooldown or delay");
        assertEquals(callbacksBeforeMissingTarget,
                legacyWeapon.outgoingCount
                        + modernWeapon.incomingCount
                        + modernWeapon.targetOutgoingCount,
                "Missing switch target should not fire weapon callbacks");

        sim.setActiveCharacter(CharacterId.AMBER);
        assertEquals(1, modernWeapon.incomingCount,
                "Direct active setter should remain callback-free");
        sim.setActiveCharacter(CharacterId.SUCROSE);
        TestCharacter plainTarget = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        sim.addCharacter(plainTarget);
        sim.switchCharacter(CharacterId.XINGQIU);
        assertEquals(CharacterId.XINGQIU,
                sim.getActiveCharacter().getCharacterId(),
                "Switching to a plain weapon should remain supported");

        List<String> order = new ArrayList<>();
        RecordingSwitchCharacter outgoing = new RecordingSwitchCharacter(
                "outgoing", CharacterId.SUCROSE, order);
        RecordingSwitchCharacter incoming = new RecordingSwitchCharacter(
                "incoming", CharacterId.AMBER, order);
        CombatSimulator orderedSim = simulatorWithExistingCharacter(outgoing);
        orderedSim.addCharacter(incoming);
        orderedSim.switchCharacter(CharacterId.AMBER);
        String[] expectedOrder = {
                "outgoing-character-out",
                "outgoing-weapon-out",
                "outgoing-artifact-out",
                "incoming-character-in",
                "incoming-weapon-in",
                "incoming-artifact-in"
        };
        assertEquals(expectedOrder.length, order.size(),
                "Standard switch should dispatch every callback exactly once");
        for (int i = 0; i < expectedOrder.length; i++) {
            assertEquals(expectedOrder[i], order.get(i),
                    "Standard switch callback order at index " + i);
        }
        assertEquals(CharacterId.SUCROSE, outgoing.activeAtSwitchOut,
                "Outgoing character callback should observe the old active member");
        assertEquals(CharacterId.AMBER, incoming.activeAtSwitchIn,
                "Incoming character callback should observe the new active member");
        assertClose(0.0, outgoing.switchOutTime, EPS,
                "Outgoing character callback should run before switch delay");
        assertClose(0.0, incoming.switchInTime, EPS,
                "Incoming character callback should run before switch delay");
        assertClose(0.1, orderedSim.getCurrentTime(), EPS,
                "Standard switch should retain its existing delay");

        int callbacksBeforeSameTarget = order.size();
        double timeBeforeSameTarget = orderedSim.getCurrentTime();
        orderedSim.switchCharacter(CharacterId.AMBER);
        assertEquals(callbacksBeforeSameTarget, order.size(),
                "Same-active switch should not dispatch callbacks");
        assertClose(timeBeforeSameTarget, orderedSim.getCurrentTime(), EPS,
                "Same-active switch should not consume cooldown or delay");

        orderedSim.setActiveCharacter(CharacterId.SUCROSE);
        assertEquals(callbacksBeforeSameTarget, order.size(),
                "Direct active setter should not dispatch character callbacks");
    }

    private static void testAccuracyPhaseF_SwitchActivatedWeapons() {
        model.weapon.TheWidsith recitative =
                new model.weapon.TheWidsith(5, () -> 0.0);
        assertEquals("The Widsith", recitative.getName(),
                "The Widsith display name");
        assertEquals(model.type.WeaponType.CATALYST,
                recitative.getWeaponType(), "The Widsith weapon type");
        assertClose(510.0, recitative.getBaseAtk(), EPS,
                "The Widsith base ATK");
        assertClose(0.551,
                recitative.getStats().get(StatType.CRIT_DMG), EPS,
                "The Widsith CRIT DMG");
        assertEquals(5, recitative.getRefinement(),
                "The Widsith default refinement contract");
        TestCharacter recitativeOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        recitativeOwner.setWeapon(recitative);
        CombatSimulator recitativeSim = simulatorWith(recitativeOwner);
        assertClose(1.20,
                effectiveStatAt(recitativeOwner, StatType.ATK_PERCENT, 0.0),
                EPS, "R5 Widsith Recitative");
        assertClose(0.0,
                effectiveStatAt(recitativeOwner, StatType.ATK_PERCENT, 10.0),
                EPS, "Widsith should expire at exactly ten seconds");

        model.weapon.TheWidsith aria =
                new model.weapon.TheWidsith(5, () -> 0.34);
        TestCharacter ariaOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        ariaOwner.setWeapon(aria);
        simulatorWith(ariaOwner);
        for (Element element : Element.values()) {
            double expectedBonus = element == Element.PHYSICAL ? 0.0 : 0.96;
            assertClose(expectedBonus,
                    effectiveStatAt(
                            ariaOwner, element.getBonusStatType(), 0.0),
                    EPS, "Widsith Aria element boundary " + element);
        }

        model.weapon.TheWidsith interlude =
                new model.weapon.TheWidsith(5, () -> 0.80);
        TestCharacter interludeOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        interludeOwner.setWeapon(interlude);
        simulatorWith(interludeOwner);
        assertClose(480.0,
                effectiveStatAt(
                        interludeOwner, StatType.ELEMENTAL_MASTERY, 0.0),
                EPS, "R5 Widsith Interlude");

        int[] drawCount = {0};
        model.weapon.TheWidsith cooldownWidsith =
                new model.weapon.TheWidsith(1, () -> {
                    drawCount[0]++;
                    return drawCount[0] == 1 ? 0.0 : 0.80;
                });
        TestCharacter cooldownOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        cooldownOwner.setWeapon(cooldownWidsith);
        CombatSimulator cooldownSim = simulatorWith(cooldownOwner);
        cooldownSim.addCharacter(testCharacter(
                Element.PYRO, CharacterId.AMBER));
        cooldownSim.setActiveCharacter(CharacterId.AMBER);
        cooldownSim.setActiveCharacter(CharacterId.SUCROSE);
        assertEquals(1, drawCount[0],
                "Direct setters should not activate Widsith");
        cooldownSim.advanceTime(29.999);
        cooldownWidsith.onSwitchIn(cooldownOwner, cooldownSim);
        assertEquals(1, drawCount[0],
                "Widsith should not draw while on cooldown");
        cooldownSim.advanceTime(0.001 + 1e-9);
        cooldownWidsith.onSwitchIn(cooldownOwner, cooldownSim);
        assertEquals(2, drawCount[0],
                "Widsith should draw at the exact cooldown boundary");
        assertClose(240.0,
                resolvedStat(cooldownSim, cooldownOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "R1 Widsith Interlude after cooldown");

        boolean invalidDrawRejected = false;
        try {
            model.weapon.TheWidsith invalid =
                    new model.weapon.TheWidsith(5, () -> 1.0);
            TestCharacter invalidOwner = testCharacter(Element.ANEMO);
            invalidOwner.setWeapon(invalid);
            simulatorWith(invalidOwner);
        } catch (IllegalArgumentException expected) {
            invalidDrawRejected = true;
        }
        assertTrue(invalidDrawRejected,
                "Widsith should reject draws outside [0, 1)");
        cooldownWidsith.initializeForSimulator(cooldownOwner, cooldownSim);
        boolean crossSimulatorWidsithRejected = false;
        try {
            cooldownWidsith.initializeForSimulator(
                    cooldownOwner, new CombatSimulator());
        } catch (IllegalStateException expected) {
            crossSimulatorWidsithRejected = true;
        }
        assertTrue(crossSimulatorWidsithRejected,
                "Widsith should reject cross-simulator reuse");

        model.weapon.SacrificialJade jade =
                new model.weapon.SacrificialJade();
        assertEquals("Sacrificial Jade", jade.getName(),
                "Sacrificial Jade display name");
        assertEquals(model.type.WeaponType.CATALYST,
                jade.getWeaponType(), "Sacrificial Jade weapon type");
        assertClose(454.0, jade.getBaseAtk(), EPS,
                "Sacrificial Jade base ATK");
        assertClose(0.368,
                jade.getStats().get(StatType.CRIT_RATE), EPS,
                "Sacrificial Jade CRIT Rate");
        assertEquals(5, jade.getRefinement(),
                "Sacrificial Jade default refinement");
        TestCharacter jadeOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        jadeOwner.setWeapon(jade);
        TestCharacter jadeAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        CombatSimulator jadeSim = simulatorWith(jadeOwner);
        jadeSim.addCharacter(jadeAlly);
        jadeSim.switchCharacter(CharacterId.AMBER);
        assertClose(0.0,
                effectiveStatAt(jadeOwner, StatType.HP_PERCENT, 4.999), EPS,
                "Sacrificial Jade before five off-field seconds");
        assertClose(0.64,
                effectiveStatAt(jadeOwner, StatType.HP_PERCENT, 5.0), EPS,
                "R5 Sacrificial Jade at five off-field seconds");
        assertClose(80.0,
                effectiveStatAt(
                        jadeOwner, StatType.ELEMENTAL_MASTERY, 5.0), EPS,
                "R5 Sacrificial Jade EM");
        jadeSim.advanceTime(4.9);
        jadeSim.switchCharacter(CharacterId.SUCROSE);
        assertClose(0.64,
                effectiveStatAt(jadeOwner, StatType.HP_PERCENT, 14.999), EPS,
                "Sacrificial Jade should retain its on-field grace");
        assertClose(0.0,
                effectiveStatAt(jadeOwner, StatType.HP_PERCENT, 15.0), EPS,
                "Sacrificial Jade should expire at exact on-field ten seconds");

        model.weapon.SacrificialJade directJade =
                new model.weapon.SacrificialJade(1);
        TestCharacter directLead = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        TestCharacter directJadeOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        directJadeOwner.setWeapon(directJade);
        CombatSimulator directJadeSim = simulatorWith(directLead);
        directJadeSim.addCharacter(directJadeOwner);
        directJadeSim.advanceTime(5.0);
        assertClose(0.32,
                resolvedStat(directJadeSim, directJadeOwner,
                        StatType.HP_PERCENT), EPS,
                "Initially off-field R1 Sacrificial Jade");
        directJadeSim.setActiveCharacter(CharacterId.SUCROSE);
        assertClose(40.0,
                resolvedStat(directJadeSim, directJadeOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "Direct setter should preserve active Jade grace coherently");

        model.weapon.ThrillingTalesOfDragonSlayers thrillingTales =
                new model.weapon.ThrillingTalesOfDragonSlayers();
        assertEquals("Thrilling Tales of Dragon Slayers",
                thrillingTales.getName(), "TTDS display name");
        assertEquals(model.type.WeaponType.CATALYST,
                thrillingTales.getWeaponType(), "TTDS weapon type");
        assertClose(401.0, thrillingTales.getBaseAtk(), EPS,
                "TTDS base ATK");
        assertClose(0.352,
                thrillingTales.getStats().get(StatType.HP_PERCENT), EPS,
                "TTDS HP percent");
        assertEquals(5, thrillingTales.getRefinement(),
                "TTDS default refinement");
        TestCharacter talesOwner = testCharacter(
                Element.ANEMO, CharacterId.SUCROSE);
        talesOwner.setWeapon(thrillingTales);
        TestCharacter talesTarget = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        CombatSimulator talesSim = simulatorWith(talesOwner);
        talesSim.addCharacter(talesTarget);
        SimulatorSnapshot talesSnapshot = talesSim.saveSnapshot();
        talesSim.switchCharacter(CharacterId.AMBER);
        assertClose(0.48,
                resolvedStat(talesSim, talesTarget, StatType.ATK_PERCENT),
                EPS, "R5 TTDS incoming target buff");
        assertEquals(1,
                (int) talesTarget.getActiveBuffs().stream()
                        .filter(buff -> buff.getId()
                                == BuffId.THRILLING_TALES_LEGACY)
                        .count(),
                "TTDS should apply one typed buff");
        talesSim.restoreSnapshot(talesSnapshot);
        talesSim.switchCharacter(CharacterId.AMBER);
        assertClose(0.48,
                resolvedStat(talesSim, talesTarget, StatType.ATK_PERCENT),
                EPS, "TTDS snapshot should restore Legacy eligibility");
        assertClose(0.0,
                effectiveStatAt(talesTarget, StatType.ATK_PERCENT, 10.0),
                EPS, "TTDS should expire at exactly ten seconds");
        talesSim.setActiveCharacter(CharacterId.SUCROSE);
        talesSim.advanceTime(19.899);
        thrillingTales.onSwitchOut(talesOwner, talesTarget, talesSim);
        assertClose(0.0,
                resolvedStat(talesSim, talesTarget, StatType.ATK_PERCENT),
                EPS, "TTDS should reject retry before twenty seconds");
        talesSim.advanceTime(0.001 + 1e-9);
        thrillingTales.onSwitchOut(talesOwner, talesTarget, talesSim);
        assertClose(0.48,
                resolvedStat(talesSim, talesTarget, StatType.ATK_PERCENT),
                EPS, "TTDS should reactivate at twenty seconds");
        assertEquals(1,
                (int) talesTarget.getActiveBuffs().stream()
                        .filter(buff -> buff.getId()
                                == BuffId.THRILLING_TALES_LEGACY)
                        .count(),
                "TTDS should replace rather than stack its typed buff");
        int talesBuffCount = talesTarget.getActiveBuffs().size();
        thrillingTales.onSwitchOut(talesOwner, null, talesSim);
        thrillingTales.onSwitchOut(talesTarget, talesOwner, talesSim);
        thrillingTales.onSwitchOut(
                talesOwner, talesTarget, new CombatSimulator());
        assertEquals(talesBuffCount, talesTarget.getActiveBuffs().size(),
                "TTDS should ignore invalid callback contexts");

        model.weapon.ThrillingTalesOfDragonSlayers r1Tales =
                new model.weapon.ThrillingTalesOfDragonSlayers(1);
        TestCharacter r1TalesOwner = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        r1TalesOwner.setWeapon(r1Tales);
        TestCharacter r1TalesTarget = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        CombatSimulator r1TalesSim = simulatorWith(r1TalesOwner);
        r1TalesSim.addCharacter(r1TalesTarget);
        r1TalesSim.switchCharacter(CharacterId.AMBER);
        assertClose(0.24,
                resolvedStat(r1TalesSim, r1TalesTarget,
                        StatType.ATK_PERCENT), EPS,
                "R1 TTDS incoming target buff");

        boolean lowWidsithRejected = false;
        boolean highJadeRejected = false;
        boolean lowTalesRejected = false;
        try {
            new model.weapon.TheWidsith(0);
        } catch (IllegalArgumentException expected) {
            lowWidsithRejected = true;
        }
        try {
            new model.weapon.SacrificialJade(6);
        } catch (IllegalArgumentException expected) {
            highJadeRejected = true;
        }
        try {
            new model.weapon.ThrillingTalesOfDragonSlayers(0);
        } catch (IllegalArgumentException expected) {
            lowTalesRejected = true;
        }
        assertTrue(lowWidsithRejected,
                "Widsith should reject refinement zero");
        assertTrue(highJadeRejected,
                "Sacrificial Jade should reject refinement six");
        assertTrue(lowTalesRejected,
                "TTDS should reject refinement zero");
    }

    private static void testAccuracyPhaseF_CoreArtifactSetsPhaseOne() {
        StatsContainer gladiatorStats = new StatsContainer();
        gladiatorStats.set(StatType.CRIT_RATE, 0.20);
        model.artifact.GladiatorsFinale suppliedGladiator =
                new model.artifact.GladiatorsFinale(gladiatorStats);
        assertEquals("Gladiator's Finale", suppliedGladiator.getName(),
                "Gladiator display name");
        assertClose(0.18,
                suppliedGladiator.getStats().get(StatType.ATK_PERCENT), EPS,
                "Gladiator two-piece ATK");
        assertClose(0.20,
                suppliedGladiator.getStats().get(StatType.CRIT_RATE), EPS,
                "Gladiator should preserve supplied stats");

        Weapon[] gladiatorWeapons = {
            new model.weapon.DullBlade(),
            new model.weapon.WasterGreatsword(),
            new model.weapon.BeginnersProtector(),
            new model.weapon.HuntersBow(),
            new model.weapon.ApprenticesNotes(),
            null
        };
        double[] expectedNormalBonuses = {0.35, 0.35, 0.35, 0.0, 0.0, 0.0};
        for (int index = 0; index < gladiatorWeapons.length; index++) {
            TestCharacter owner = testCharacter(Element.PHYSICAL);
            owner.setWeapon(gladiatorWeapons[index]);
            owner.setArtifacts(new model.artifact.GladiatorsFinale());
            simulatorWith(owner);
            assertClose(0.18,
                    effectiveStatAt(owner, StatType.ATK_PERCENT, 0.0), EPS,
                    "Gladiator static ATK for weapon index " + index);
            assertClose(expectedNormalBonuses[index],
                    effectiveStatAt(
                            owner, StatType.NORMAL_ATTACK_DMG_BONUS, 0.0),
                    EPS, "Gladiator weapon gate index " + index);
        }

        StatsContainer goldenStats = new StatsContainer();
        goldenStats.set(StatType.CRIT_DMG, 0.40);
        model.artifact.GoldenTroupe suppliedGolden =
                new model.artifact.GoldenTroupe(goldenStats);
        assertEquals("Golden Troupe", suppliedGolden.getName(),
                "Golden Troupe display name");
        assertClose(0.45,
                suppliedGolden.getStats().get(StatType.SKILL_DMG_BONUS), EPS,
                "Golden Troupe fixed Skill bonus");
        assertClose(0.40,
                suppliedGolden.getStats().get(StatType.CRIT_DMG), EPS,
                "Golden Troupe should preserve supplied stats");

        TestCharacter goldenLead = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        model.artifact.GoldenTroupe goldenTroupe =
                new model.artifact.GoldenTroupe();
        TestCharacter goldenOwner = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        goldenOwner.setArtifacts(goldenTroupe);
        CombatSimulator goldenSim = simulatorWith(goldenLead);
        goldenSim.addCharacter(goldenOwner);
        assertClose(0.70,
                effectiveStatAt(
                        goldenOwner, StatType.SKILL_DMG_BONUS, 0.0), EPS,
                "Initially off-field Golden Troupe");
        goldenSim.switchCharacter(CharacterId.XINGQIU);
        assertClose(0.70,
                resolvedStat(goldenSim, goldenOwner,
                        StatType.SKILL_DMG_BONUS), EPS,
                "Golden Troupe switch-in grace");
        goldenSim.advanceTime(1.899);
        assertClose(0.70,
                resolvedStat(goldenSim, goldenOwner,
                        StatType.SKILL_DMG_BONUS), EPS,
                "Golden Troupe before exact grace expiry");
        goldenSim.advanceTime(0.001 + 1e-9);
        assertClose(0.45,
                resolvedStat(goldenSim, goldenOwner,
                        StatType.SKILL_DMG_BONUS), EPS,
                "Golden Troupe at exact two-second grace expiry");
        goldenSim.switchCharacter(CharacterId.AMBER);
        assertClose(0.70,
                resolvedStat(goldenSim, goldenOwner,
                        StatType.SKILL_DMG_BONUS), EPS,
                "Golden Troupe immediately after switch-out");
        goldenSim.switchCharacter(CharacterId.XINGQIU);
        assertClose(0.70,
                resolvedStat(goldenSim, goldenOwner,
                        StatType.SKILL_DMG_BONUS), EPS,
                "Golden Troupe repeated switch-in grace");

        model.artifact.GoldenTroupe directGolden =
                new model.artifact.GoldenTroupe();
        TestCharacter directGoldenOwner = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        directGoldenOwner.setArtifacts(directGolden);
        TestCharacter directGoldenAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        CombatSimulator directGoldenSim = simulatorWith(directGoldenOwner);
        directGoldenSim.addCharacter(directGoldenAlly);
        directGoldenSim.setActiveCharacter(CharacterId.AMBER);
        assertClose(0.70,
                resolvedStat(directGoldenSim, directGoldenOwner,
                        StatType.SKILL_DMG_BONUS), EPS,
                "Direct setter off-field Golden Troupe");
        directGoldenSim.setActiveCharacter(CharacterId.XINGQIU);
        assertClose(0.45,
                resolvedStat(directGoldenSim, directGoldenOwner,
                        StatType.SKILL_DMG_BONUS), EPS,
                "Direct setter should not fabricate switch-in grace");

        goldenTroupe.initializeForSimulator(goldenOwner, goldenSim, false);
        boolean goldenCrossSimulatorRejected = false;
        try {
            goldenTroupe.initializeForSimulator(
                    goldenOwner, new CombatSimulator(), false);
        } catch (IllegalStateException expected) {
            goldenCrossSimulatorRejected = true;
        }
        assertTrue(goldenCrossSimulatorRejected,
                "Golden Troupe should reject cross-simulator reuse");
        boolean nullGladiatorStatsRejected = false;
        try {
            new model.artifact.GladiatorsFinale(null);
        } catch (NullPointerException expected) {
            nullGladiatorStatsRejected = true;
        }
        assertTrue(nullGladiatorStatsRejected,
                "Gladiator should reject null supplied stats");
    }

    private static void testAccuracyPhaseF_CoreArtifactSetsPhaseTwo() {
        StatsContainer gildedStats = new StatsContainer();
        gildedStats.set(StatType.CRIT_RATE, 0.25);
        model.artifact.GildedDreams suppliedGilded =
                new model.artifact.GildedDreams(gildedStats);
        assertEquals("Gilded Dreams", suppliedGilded.getName(),
                "Gilded Dreams display name");
        assertClose(80.0,
                suppliedGilded.getStats().get(StatType.ELEMENTAL_MASTERY),
                EPS, "Gilded Dreams two-piece EM");
        assertClose(0.25,
                suppliedGilded.getStats().get(StatType.CRIT_RATE), EPS,
                "Gilded Dreams should preserve supplied stats");

        model.artifact.GildedDreams gilded =
                new model.artifact.GildedDreams();
        TestCharacter gildedOwner = testCharacter(
                Element.DENDRO, CharacterId.SUCROSE);
        gildedOwner.setArtifacts(gilded);
        TestCharacter sameElementAlly = testCharacter(
                Element.DENDRO, CharacterId.FLINS);
        TestCharacter differentElementAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        CombatSimulator gildedSim = simulatorWith(gildedOwner);
        gildedSim.addCharacter(sameElementAlly);
        gildedSim.addCharacter(differentElementAlly);
        gildedSim.setActiveCharacter(CharacterId.AMBER);
        ReactionResult gildedReaction = ReactionResult.transform(
                0.0, "Gilded Bloom", ReactionResult.Kind.BLOOM);
        gildedSim.notifyReaction(ReactionResult.none(), gildedOwner);
        gildedSim.notifyReaction(gildedReaction, differentElementAlly);
        assertClose(0.0,
                resolvedStat(gildedSim, gildedOwner, StatType.ATK_PERCENT),
                EPS, "Invalid Gilded triggers should not grant ATK");
        assertClose(80.0,
                resolvedStat(gildedSim, gildedOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "Invalid Gilded triggers should retain only two-piece EM");
        gildedSim.notifyReaction(gildedReaction, gildedOwner);
        assertClose(0.14,
                resolvedStat(gildedSim, gildedOwner, StatType.ATK_PERCENT),
                EPS, "Gilded same-element composition snapshot");
        assertClose(130.0,
                resolvedStat(gildedSim, gildedOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "Off-field Gilded different-element snapshot");

        TestCharacter laterDifferentAlly = testCharacter(
                Element.HYDRO, CharacterId.XINGQIU);
        gildedSim.addCharacter(laterDifferentAlly);
        assertClose(130.0,
                resolvedStat(gildedSim, gildedOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "Gilded should retain its composition snapshot");
        gildedSim.advanceTime(7.999);
        gildedSim.notifyReaction(gildedReaction, gildedOwner);
        assertClose(130.0,
                resolvedStat(gildedSim, gildedOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "Gilded should not refresh before eight seconds");
        gildedSim.advanceTime(0.001 + 1e-9);
        gildedSim.notifyReaction(gildedReaction, gildedOwner);
        assertClose(180.0,
                resolvedStat(gildedSim, gildedOwner,
                        StatType.ELEMENTAL_MASTERY), EPS,
                "Gilded should resnapshot at exact eight-second boundary");
        gilded.initializeForSimulator(gildedOwner, gildedSim, true);
        boolean gildedCrossSimulatorRejected = false;
        try {
            gilded.initializeForSimulator(
                    gildedOwner, new CombatSimulator(), true);
        } catch (IllegalStateException expected) {
            gildedCrossSimulatorRejected = true;
        }
        assertTrue(gildedCrossSimulatorRejected,
                "Gilded Dreams should reject cross-simulator reuse");

        StatsContainer paleStats = new StatsContainer();
        paleStats.set(StatType.CRIT_DMG, 0.30);
        model.artifact.PaleFlame suppliedPale =
                new model.artifact.PaleFlame(paleStats);
        assertEquals("Pale Flame", suppliedPale.getName(),
                "Pale Flame display name");
        assertClose(0.25,
                suppliedPale.getStats().get(StatType.PHYSICAL_DMG_BONUS),
                EPS, "Pale Flame two-piece Physical bonus");
        assertClose(0.30,
                suppliedPale.getStats().get(StatType.CRIT_DMG), EPS,
                "Pale Flame should preserve supplied stats");

        model.artifact.PaleFlame paleFlame =
                new model.artifact.PaleFlame();
        TestCharacter paleOwner = testCharacter(
                Element.PHYSICAL, CharacterId.SUCROSE);
        paleOwner.setArtifacts(paleFlame);
        CombatSimulator paleSim = simulatorWith(paleOwner);
        AttackAction skillHit = typedDamageHit(
                "Pale Flame Skill fixture", ActionType.SKILL, 1.0);
        AttackAction normalHit = typedDamageHit(
                "Pale Flame Normal fixture", ActionType.NORMAL, 1.0);
        assertClose(0.25,
                resolvedStat(paleSim, paleOwner,
                        StatType.PHYSICAL_DMG_BONUS), EPS,
                "Pale Flame initial Physical bonus");
        paleFlame.onDamage(paleSim, normalHit, 100.0, paleOwner);
        paleFlame.onDamage(paleSim, skillHit, 0.0, paleOwner);
        assertClose(0.0,
                resolvedStat(paleSim, paleOwner, StatType.ATK_PERCENT),
                EPS, "Pale Flame should reject non-Skill and zero damage");
        paleFlame.onDamage(paleSim, skillHit, 100.0, paleOwner);
        assertClose(0.09,
                resolvedStat(paleSim, paleOwner, StatType.ATK_PERCENT),
                EPS, "Pale Flame first stack");
        assertClose(0.25,
                resolvedStat(paleSim, paleOwner,
                        StatType.PHYSICAL_DMG_BONUS), EPS,
                "One Pale Flame stack should not double Physical bonus");
        paleSim.advanceTime(0.299);
        paleFlame.onDamage(paleSim, skillHit, 100.0, paleOwner);
        assertClose(0.09,
                resolvedStat(paleSim, paleOwner, StatType.ATK_PERCENT),
                EPS, "Pale Flame stack CT before 0.3 seconds");
        paleSim.advanceTime(0.001 + 1e-9);
        paleFlame.onDamage(paleSim, skillHit, 100.0, paleOwner);
        assertClose(0.18,
                resolvedStat(paleSim, paleOwner, StatType.ATK_PERCENT),
                EPS, "Pale Flame second stack at exact CT");
        assertClose(0.50,
                resolvedStat(paleSim, paleOwner,
                        StatType.PHYSICAL_DMG_BONUS), EPS,
                "Pale Flame doubled Physical bonus at two stacks");
        paleSim.advanceTime(6.999);
        assertClose(0.18,
                resolvedStat(paleSim, paleOwner, StatType.ATK_PERCENT),
                EPS, "Pale Flame before shared expiry");
        paleSim.advanceTime(0.001 + 1e-9);
        assertClose(0.0,
                resolvedStat(paleSim, paleOwner, StatType.ATK_PERCENT),
                EPS, "Pale Flame at exact seven-second expiry");
        assertClose(0.25,
                resolvedStat(paleSim, paleOwner,
                        StatType.PHYSICAL_DMG_BONUS), EPS,
                "Expired Pale stacks should retain only two-piece Physical bonus");

        model.artifact.PaleFlame independentPale =
                new model.artifact.PaleFlame();
        TestCharacter independentOwner = testCharacter(Element.PHYSICAL);
        independentOwner.setArtifacts(independentPale);
        CombatSimulator independentSim = simulatorWith(independentOwner);
        assertClose(0.0,
                resolvedStat(independentSim, independentOwner,
                        StatType.ATK_PERCENT), EPS,
                "Pale Flame instances should keep independent stacks");
        paleFlame.onDamage(
                new CombatSimulator(), skillHit, 100.0, paleOwner);
        paleFlame.onDamage(paleSim, skillHit, 100.0, independentOwner);
        assertClose(0.0,
                resolvedStat(independentSim, independentOwner,
                        StatType.ATK_PERCENT), EPS,
                "Pale Flame should reject wrong callback bindings");

        boolean nullGildedStatsRejected = false;
        boolean nullPaleStatsRejected = false;
        try {
            new model.artifact.GildedDreams(null);
        } catch (NullPointerException expected) {
            nullGildedStatsRejected = true;
        }
        try {
            new model.artifact.PaleFlame(null);
        } catch (NullPointerException expected) {
            nullPaleStatsRejected = true;
        }
        assertTrue(nullGildedStatsRejected,
                "Gilded Dreams should reject null supplied stats");
        assertTrue(nullPaleStatsRejected,
                "Pale Flame should reject null supplied stats");
    }

    private static void testAccuracyPhaseF_ExpandedArtifactSetsPhaseOne() {
        StatsContainer wandererStats = new StatsContainer();
        wandererStats.set(StatType.CRIT_RATE, 0.15);
        model.artifact.WanderersTroupe suppliedWanderer =
                new model.artifact.WanderersTroupe(wandererStats);
        assertEquals("Wanderer's Troupe", suppliedWanderer.getName(),
                "Wanderer's Troupe display name");
        assertClose(80.0,
                suppliedWanderer.getStats().get(StatType.ELEMENTAL_MASTERY),
                EPS, "Wanderer's Troupe two-piece EM");
        assertClose(0.15,
                suppliedWanderer.getStats().get(StatType.CRIT_RATE), EPS,
                "Wanderer's Troupe should preserve supplied stats");

        Weapon[] wandererWeapons = {
            new model.weapon.DullBlade(),
            new model.weapon.WasterGreatsword(),
            new model.weapon.BeginnersProtector(),
            new model.weapon.HuntersBow(),
            new model.weapon.ApprenticesNotes(),
            null
        };
        for (int index = 0; index < wandererWeapons.length; index++) {
            TestCharacter owner = testCharacter(Element.ANEMO);
            owner.setWeapon(wandererWeapons[index]);
            owner.setArtifacts(new model.artifact.WanderersTroupe());
            simulatorWith(owner);
            double expectedChargedBonus = index == 3 || index == 4
                    ? 0.35 : 0.0;
            assertClose(80.0,
                    effectiveStatAt(
                            owner, StatType.ELEMENTAL_MASTERY, 0.0), EPS,
                    "Wanderer's Troupe static EM index " + index);
            assertClose(expectedChargedBonus,
                    effectiveStatAt(
                            owner, StatType.CHARGED_ATTACK_DMG_BONUS, 0.0),
                    EPS, "Wanderer's Troupe weapon gate index " + index);
        }

        StatsContainer finaleStats = new StatsContainer();
        finaleStats.set(StatType.CRIT_DMG, 0.25);
        model.artifact.FinaleOfTheDeepGalleries suppliedFinale =
                new model.artifact.FinaleOfTheDeepGalleries(finaleStats);
        assertEquals("Finale of the Deep Galleries", suppliedFinale.getName(),
                "Finale display name");
        assertClose(0.15,
                suppliedFinale.getStats().get(StatType.CRYO_DMG_BONUS), EPS,
                "Finale two-piece Cryo bonus");
        assertClose(0.25,
                suppliedFinale.getStats().get(StatType.CRIT_DMG), EPS,
                "Finale should preserve supplied stats");

        model.artifact.FinaleOfTheDeepGalleries finale =
                new model.artifact.FinaleOfTheDeepGalleries();
        TestCharacter finaleOwner = testCharacter(
                Element.CRYO, CharacterId.SUCROSE);
        finaleOwner.setArtifacts(finale);
        CombatSimulator finaleSim = simulatorWith(finaleOwner);
        finaleOwner.restoreCurrentEnergy(0.0);
        assertClose(0.60,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS), EPS,
                "Finale zero-Energy Normal bonus");
        assertClose(0.60,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.BURST_DMG_BONUS), EPS,
                "Finale zero-Energy Burst bonus");
        AttackAction finaleNormal = typedDamageHit(
                "Finale Normal fixture", ActionType.NORMAL, 1.0);
        AttackAction finaleBurst = typedDamageHit(
                "Finale Burst fixture", ActionType.BURST, 1.0);
        AttackAction finaleSkill = typedDamageHit(
                "Finale Skill fixture", ActionType.SKILL, 1.0);
        finale.onDamage(finaleSim, finaleSkill, 100.0, finaleOwner);
        finale.onDamage(finaleSim, finaleNormal, 0.0, finaleOwner);
        assertClose(0.60,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.BURST_DMG_BONUS), EPS,
                "Finale should reject Skill and zero-damage callbacks");
        finale.onDamage(finaleSim, finaleNormal, 100.0, finaleOwner);
        assertClose(0.60,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS), EPS,
                "Finale Normal hit should retain Normal bonus");
        assertClose(0.0,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.BURST_DMG_BONUS), EPS,
                "Finale Normal hit should suppress Burst bonus");
        finaleOwner.restoreCurrentEnergy(10.0);
        assertClose(0.0,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS), EPS,
                "Finale should require exactly zero Energy");
        finaleOwner.restoreCurrentEnergy(0.0);
        finaleSim.advanceTime(5.999);
        assertClose(0.0,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.BURST_DMG_BONUS), EPS,
                "Finale before Burst lock expiry");
        finaleSim.advanceTime(0.001 + 1e-9);
        assertClose(0.60,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.BURST_DMG_BONUS), EPS,
                "Finale at exact Burst lock expiry");
        finale.onDamage(finaleSim, finaleBurst, 100.0, finaleOwner);
        assertClose(0.0,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS), EPS,
                "Finale Burst hit should suppress Normal bonus");
        assertClose(0.60,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.BURST_DMG_BONUS), EPS,
                "Finale Burst hit should retain Burst bonus");

        TestCharacter finaleAlly = testCharacter(
                Element.PYRO, CharacterId.AMBER);
        finaleSim.addCharacter(finaleAlly);
        finaleSim.setActiveCharacter(CharacterId.AMBER);
        finaleSim.advanceTime(6.0);
        finale.onDamage(finaleSim, finaleBurst, 100.0, finaleOwner);
        assertClose(0.0,
                resolvedStat(finaleSim, finaleOwner,
                        StatType.NORMAL_ATTACK_DMG_BONUS), EPS,
                "Finale should accept off-field Burst damage");
        finale.onDamage(
                new CombatSimulator(), finaleNormal, 100.0, finaleOwner);
        finale.onDamage(finaleSim, finaleNormal, 100.0, finaleAlly);

        finale.initializeForSimulator(finaleOwner, finaleSim, false);
        boolean finaleCrossSimulatorRejected = false;
        try {
            finale.initializeForSimulator(
                    finaleOwner, new CombatSimulator(), false);
        } catch (IllegalStateException expected) {
            finaleCrossSimulatorRejected = true;
        }
        assertTrue(finaleCrossSimulatorRejected,
                "Finale should reject cross-simulator reuse");
        boolean nullWandererStatsRejected = false;
        boolean nullFinaleStatsRejected = false;
        try {
            new model.artifact.WanderersTroupe(null);
        } catch (NullPointerException expected) {
            nullWandererStatsRejected = true;
        }
        try {
            new model.artifact.FinaleOfTheDeepGalleries(null);
        } catch (NullPointerException expected) {
            nullFinaleStatsRejected = true;
        }
        assertTrue(nullWandererStatsRejected,
                "Wanderer's Troupe should reject null supplied stats");
        assertTrue(nullFinaleStatsRejected,
                "Finale should reject null supplied stats");
    }

